import { one, query, tsPool } from '../db/pool.js';
import { round } from '../lib/stats.js';
import { primarySummary, primaryTransactions, infraAggregates } from '../analytics/summary.js';
import { compareRuns, resolveBaseline } from '../analytics/compare.js';
import { loadTrend, TREND_METRICS, type TrendMetric } from '../analytics/trends.js';
import { capacityModel } from '../analytics/capacity.js';
import { runSeries, infraSeries } from '../metrics/series.js';
import { reconcile } from './reconcile.js';

/**
 * Report model (docs/architecture/api-contracts.md §8). Built only from stored analysis data
 * (run_summary, transactions, sla_results, regressions, insights, recommendations, metrics) —
 * every export format renders from this object, so a report is reproducible from its params.
 *
 * Layout: `chapter` sections start a numbered chapter (1, 2, …); the sections that follow are its
 * numbered sub-sections (1.1, 1.2, …). Reports stored before chapters existed simply have none.
 * Never invent numbers: a value that is not stored is null ("n/a"); approximations carry `approx`.
 */
export type SectionKind = 'chapter' | 'summary' | 'kv' | 'kpis' | 'table' | 'text' | 'list' | 'findings' | 'chart';
export type ColumnFmt = 'int' | 'num' | 'num1' | 'ms' | 'pct' | 'delta' | 'status' | 'spark' | 'text' | 'date' | 'mono';
export interface Column { key: string; header: string; unit?: string; fmt?: ColumnFmt; approx?: boolean }
export interface Kpi { label: string; value: number | string | null; unit?: string; status?: string | null; baseline?: number | null; deltaPct?: number | null; better?: 'lower' | 'higher' | 'neutral'; approx?: boolean; hint?: string }
export interface Finding { severity: string; title: string; description: string }
export interface ChartSeries { name: string; data: [number | string, number | null][]; style?: 'solid' | 'dashed' | 'dotted' }
export interface ChartData {
  type: 'line' | 'bar'; unit?: string; xType?: 'time' | 'category' | 'elapsed'; series: ChartSeries[];
  yLabel?: string; thresholds?: { label: string; value: number; status?: string }[];
}
export interface SummaryData {
  paragraphs: string[];
  findings: { text: string; tone?: 'pass' | 'warn' | 'fail' | null }[];
  recommendations: { text: string; priority?: string | null }[];
  risk: { level: 'LOW' | 'MEDIUM' | 'HIGH'; reason: string };
}
export interface Section { id: string; title: string; kind: SectionKind; data: any; note?: string }
export interface ReportContent {
  title: string; type: string; generatedAt: string; version: number; audience: 'EXECUTIVE' | 'ENGINEERING';
  subject: { runKey?: string; runKeys?: string[]; testName?: string; projectName?: string; environment?: string; build?: string; from?: string; to?: string };
  result?: { status: string; score: number | null; breakdown: Record<string, string>; reasons?: string[] };
  sections: Section[];
  /** set by the generator (report row id) */
  reportId?: string;
  confidentiality?: string;
  /** cover facts shown on the title page */
  cover?: { label: string; facts: [string, string][] };
  schema?: number;
}

const n = (v: unknown): number | null => (v == null || v === '' || !Number.isFinite(Number(v)) ? null : Number(v));
const r2 = (v: unknown, d = 2) => round(n(v), d);
const iso = (v: unknown) => (v ? new Date(v as string).toISOString() : null);
const day = (v: unknown) => (v ? new Date(v as string).toISOString().slice(0, 10) : '—');
const sevRank = (s: string) => (s === 'CRITICAL' || s === 'HIGH' ? 0 : s === 'WARNING' || s === 'MEDIUM' ? 1 : 2);
const pctOf = (a: number | null, b: number | null) => (a == null || b == null || b === 0 ? null : (a / b) * 100);
const delta = (cur: number | null, base: number | null) => (cur == null || base == null || base === 0 ? null : ((cur - base) / Math.abs(base)) * 100);
const avgOf = (xs: (number | null)[]) => { const v = xs.filter((x): x is number => x != null && Number.isFinite(x)); return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null; };
const plural = (k: number, w: string, p = `${w}s`) => `${k} ${k === 1 ? w : p}`;
export const CONFIDENTIALITY = 'Confidential — for internal use only. Generated by Perfmon from stored test data.';
export const SOURCE_LABEL: Record<string, string> = { live: 'Live listener', jtl: 'JTL results file', html_report: 'JMeter HTML report', import: 'Imported results' };
const METHOD_LABEL: Record<string, string> = { exact_histogram: 'merged latency histograms (±2.5%)', interval_weighted_approx: 'interval-weighted approximation (≈)', source_reported: 'as reported by the source' };
const SLA_METRIC_LABEL: Record<string, string> = { avg_rt: 'Average RT', p50: 'P50', p90: 'P90', p95: 'P95', p99: 'P99', max_rt: 'Max RT', error_pct: 'Error rate', tps: 'Throughput', cpu_pct: 'CPU', memory_pct: 'Memory', heap_pct: 'Heap', gc_pause_ms: 'GC pause', db_latency_ms: 'DB latency' };

/* ------------------------------------------------------------------ small builders */

const chapter = (id: string, title: string, intro?: string): Section => ({ id, title, kind: 'chapter', data: { intro } });
const col = (key: string, header: string, fmt?: ColumnFmt, unit?: string, approx?: boolean): Column => ({ key, header, fmt, unit, approx: approx || undefined });
const table = (id: string, title: string, columns: Column[], rows: Record<string, unknown>[], note?: string): Section => ({ id, title, kind: 'table', data: { columns, rows }, note });
const chart = (id: string, title: string, data: ChartData, note?: string): Section => ({ id, title, kind: 'chart', data, note });
const kv = (id: string, title: string, items: [string, unknown][], note?: string): Section => ({ id, title, kind: 'kv', data: items, note });

/** Margin to the SLA limit (critical, else warning) in % of the limit; positive = headroom. */
function slaMargin(actual: number | null, warning: number | null, critical: number | null, direction: string) {
  const lim = critical ?? warning;
  if (actual == null || lim == null || lim === 0) return null;
  return direction === 'HIGHER' ? ((actual - lim) / Math.abs(lim)) * 100 : ((lim - actual) / Math.abs(lim)) * 100;
}
const METRIC_NAME: Record<string, string> = { ...SLA_METRIC_LABEL, error_pct: 'Error %', avg_rt: 'Avg RT', tps: 'TPS', tps_peak: 'Peak TPS', cpu_avg: 'CPU avg', cpu_max: 'CPU max', mem_max: 'Memory max', heap_pct_max: 'Heap max', gc_pause_max: 'GC pause max', db_latency_avg: 'DB latency avg', db_active_max: 'DB connections max' };
const metricName = (m: unknown) => METRIC_NAME[String(m)] ?? String(m).replace(/_/g, ' ').toUpperCase();
/** "TPS (tps)" → "TPS"; "Avg RT (ms)" stays */
const metricLabel = (m: { label: string; unit: string }) => (m.unit && !m.label.toLowerCase().includes(m.unit.toLowerCase()) ? `${m.label} (${m.unit})` : m.label);
const slaRuleName = (x: any) => x.rule_name ?? `${SLA_METRIC_LABEL[x.metric] ?? x.metric} ${x.direction === 'HIGHER' ? '≥' : '≤'} ${fmtNum(n(x.critical_value ?? x.warning_value), 2)}${x.unit ? ' ' + x.unit : ''}`;

function methodology(method: string | null | undefined): string[] {
  const out = [
    'All figures in this report are read from the analysis Perfmon stored for the run(s): run summaries, per-transaction statistics, time-series buckets, SLA evaluations, regression detection, insights and infrastructure metrics. Nothing is estimated unless it is explicitly labelled as an estimate.',
    'Throughput (TPS) is the number of completed samples divided by the measured duration. Peak TPS uses windows of at least 5 seconds to avoid single-second noise. Error rate is failed samples divided by all samples.',
  ];
  if (method === 'interval_weighted_approx') out.push('Percentiles for this data source are APPROXIMATIONS (marked ≈): the load generator reported percentiles per interval and Perfmon combined them as a sample-weighted average. Interval-weighted percentiles can differ from percentiles computed over all raw samples, especially for P99.');
  else if (method === 'source_reported') out.push('Percentiles are shown exactly as reported by the data source (single aggregate); they were not recomputed by Perfmon.');
  else out.push('Percentiles are computed by merging log-bucketed latency histograms recorded for every sample (relative accuracy about ±2.5%, the bucket resolution). Per-bucket percentiles over time are computed the same way.');
  out.push('SLA rules are evaluated against the run-level or per-transaction value. A rule passes below its warning threshold, warns between warning and critical, and fails beyond critical. "Margin" is the distance to the limit (critical, else warning) as a percentage of that limit; a negative margin means the limit was exceeded.');
  out.push('Baseline comparison uses the run\'s explicit baseline, else the test baseline, else the previous completed run of the same test and environment. Changes under 2% are treated as neutral. Bottleneck confidence is a 0–100% correlation score between load and resource signals — it indicates likelihood, not certainty.');
  return out;
}

const GLOSSARY: [string, string][] = [
  ['Sample / request', 'One measured request or transaction execution reported by the load generator.'],
  ['TPS', 'Transactions (samples) per second — throughput.'],
  ['Average RT', 'Mean response time of all samples, in milliseconds.'],
  ['P50 / P90 / P95 / P99', 'Percentiles: the response time below which 50 / 90 / 95 / 99% of samples completed.'],
  ['Std-dev', 'Standard deviation of response times — spread around the mean.'],
  ['Error rate', 'Failed samples as a percentage of all samples.'],
  ['Virtual users', 'Concurrent simulated users (threads) generating load.'],
  ['SLA', 'Service-level rule: metric, direction, warning and critical thresholds.'],
  ['Baseline', 'Reference run used for change detection.'],
  ['Regression', 'A statistically relevant degradation against the baseline beyond the configured threshold.'],
  ['Performance score', '0–100 weighted score across SLA, response time, throughput, errors, infrastructure and regressions.'],
  ['Headroom', 'Estimated remaining capacity before saturation or SLA breach (always an estimate).'],
  ['≈', 'Approximate value (e.g. interval-weighted percentile or a model estimate).'],
];

/* ------------------------------------------------------------------ Test execution */

const RUN_SELECT = `
  SELECT r.*, t.name AS test_name, t.test_type, t.description AS test_description, t.owner AS test_owner, t.sla_profile_id,
         p.name AS project_name, a.name AS application_name, e.name AS environment_name, e.type AS environment_type,
         rel.version AS release_version, rel.name AS release_name, b.run_key AS baseline_key, sp.name AS sla_profile_name,
         c.virtual_users AS cfg_users, c.ramp_up_sec, c.ramp_down_sec, c.duration_sec AS cfg_duration, c.target_tps AS cfg_target_tps,
         c.thread_group, c.think_time_ms, c.version AS cfg_version
  FROM test_runs r
  JOIN performance_tests t ON t.id = r.test_id
  JOIN projects p ON p.id = r.project_id
  JOIN applications a ON a.id = r.application_id
  JOIN environments e ON e.id = r.environment_id
  LEFT JOIN releases rel ON rel.id = r.release_id
  LEFT JOIN test_runs b ON b.id = r.baseline_run_id
  LEFT JOIN sla_profiles sp ON sp.id = t.sla_profile_id
  LEFT JOIN LATERAL (SELECT * FROM test_configurations tc WHERE tc.id = r.test_configuration_id
                     OR (r.test_configuration_id IS NULL AND tc.test_id = r.test_id AND tc.is_current) ORDER BY tc.version DESC LIMIT 1) c ON true`;

export async function buildTestExecutionContent(runId: string, version: number, title: string): Promise<ReportContent> {
  const run = await one(`${RUN_SELECT} WHERE r.id = $1`, [runId]);
  if (!run) throw new Error(`run ${runId} not found`);
  const s = await primarySummary(runId);
  const baseline = await resolveBaseline(runId);
  const baseSummary = baseline ? await primarySummary(baseline.id) : null;
  const [txns, sla, regs, insights, recs, errGroups, errTypes, codes, sources, artifacts, servers, jvms, dbs, services] = await Promise.all([
    primaryTransactions(runId),
    query(`SELECT s.*, r.name AS rule_name FROM sla_results s LEFT JOIN sla_rules r ON r.id = s.rule_id WHERE s.run_id = $1
           ORDER BY CASE s.status WHEN 'FAIL' THEN 0 WHEN 'WARNING' THEN 1 WHEN 'PASS' THEN 2 ELSE 3 END, s.scope, s.metric, s.transaction`, [runId]),
    query(`SELECT g.* FROM regressions g WHERE g.run_id = $1
           ORDER BY g.direction, CASE g.severity WHEN 'CRITICAL' THEN 0 WHEN 'WARNING' THEN 1 ELSE 2 END, abs(g.change_pct) DESC NULLS LAST`, [runId]),
    query(`SELECT * FROM insights WHERE run_id = $1 ORDER BY CASE severity WHEN 'CRITICAL' THEN 0 WHEN 'WARNING' THEN 1 ELSE 2 END, confidence DESC NULLS LAST, created_at`, [runId]),
    query(`SELECT * FROM recommendations WHERE run_id = $1 ORDER BY CASE priority WHEN 'HIGH' THEN 0 WHEN 'MEDIUM' THEN 1 ELSE 2 END, created_at`, [runId]),
    query(`SELECT error_type, COALESCE(response_code, '') AS response_code, (array_agg(message ORDER BY count DESC))[1] AS message, sum(count)::int AS n,
                  count(DISTINCT transaction)::int AS txns, min(ts) AS first_ts, max(ts) AS last_ts
           FROM error_metrics WHERE run_id = $1 GROUP BY 1, 2, message ORDER BY 4 DESC LIMIT 15`, [runId]),
    query(`SELECT error_type, sum(count)::int AS n FROM error_metrics WHERE run_id = $1 GROUP BY 1 ORDER BY 2 DESC`, [runId]),
    query(`SELECT response_code, sum(count) FILTER (WHERE NOT success)::bigint AS failed, sum(count)::bigint AS n FROM response_code_metrics WHERE run_id = $1
             AND source = (SELECT source FROM response_code_metrics WHERE run_id = $1 ORDER BY CASE source WHEN 'live' THEN 0 WHEN 'jtl' THEN 1 ELSE 2 END LIMIT 1)
           GROUP BY 1 ORDER BY 3 DESC LIMIT 20`, [runId]),
    query(`SELECT source, total_samples, duration_sec, percentile_method, computed_at FROM run_summary WHERE run_id = $1
           ORDER BY CASE source WHEN 'live' THEN 0 WHEN 'jtl' THEN 1 WHEN 'import' THEN 2 ELSE 3 END`, [runId]),
    query(`SELECT a.kind, a.name, a.source, a.current_version, v.size_bytes, v.uploaded_at, v.uploaded_by_name, v.processing_status
           FROM artifacts a LEFT JOIN artifact_versions v ON v.artifact_id = a.id AND v.version = a.current_version
           WHERE a.run_id = $1 AND a.deleted_at IS NULL ORDER BY a.kind, a.name`, [runId]),
    query(`SELECT s.id, s.name, s.role, s.hostname, s.cpu_cores, s.memory_mb, avg(m.cpu_pct) cpu_avg, max(m.cpu_pct) cpu_max,
                  percentile_cont(0.95) WITHIN GROUP (ORDER BY m.cpu_pct) cpu_p95, avg(m.memory_pct) mem_avg, max(m.memory_pct) mem_max, max(m.disk_pct) disk_max,
                  avg(COALESCE(m.disk_read_bps, 0) + COALESCE(m.disk_write_bps, 0)) disk_io, avg(m.net_in_bps) net_in, avg(m.net_out_bps) net_out, max(m.load_avg_1m) load_max
           FROM server_metrics m JOIN servers s ON s.id = m.server_id WHERE m.run_id = $1 GROUP BY s.id ORDER BY s.role, s.name`, [runId], tsPool),
    query(`SELECT j.service_id, COALESCE(sv.name, s.name, 'JVM') AS name, max(j.heap_used_mb / NULLIF(j.heap_max_mb, 0) * 100) heap_max, avg(j.heap_used_mb / NULLIF(j.heap_max_mb, 0) * 100) heap_avg,
                  max(j.heap_max_mb) heap_size, max(j.gc_max_pause_ms) gc_pause_max, avg(j.gc_time_ms) gc_time_avg, max(j.thread_count) threads_max
           FROM jvm_metrics j LEFT JOIN services sv ON sv.id = j.service_id LEFT JOIN servers s ON s.id = j.server_id WHERE j.run_id = $1 GROUP BY 1, 2 ORDER BY 2`, [runId], tsPool),
    query(`SELECT COALESCE(sv.name, s.name, max(d.db_engine), 'Database') AS name, max(d.db_engine) engine, avg(d.query_latency_ms) lat_avg, max(d.query_latency_ms) lat_max,
                  max(d.active_connections) act_max, max(d.max_connections) conn_limit, max(d.active_connections::float / NULLIF(d.max_connections, 0) * 100) pool_max,
                  sum(d.slow_queries) slow, max(d.locks) locks_max, max(d.deadlocks) deadlocks, avg(d.transactions_per_sec) tps_avg, avg(d.cpu_pct) cpu_avg
           FROM database_metrics d LEFT JOIN services sv ON sv.id = d.service_id LEFT JOIN servers s ON s.id = d.server_id WHERE d.run_id = $1 GROUP BY sv.name, s.name ORDER BY 1`, [runId], tsPool),
    query(`SELECT sv.name, sv.kind, avg(m.request_rate) rate, avg(m.error_rate_pct) err_avg, max(m.error_rate_pct) err_max, avg(m.avg_latency_ms) lat_avg, max(m.p95_latency_ms) p95_max,
                  sum(m.exceptions) exceptions, avg(m.cpu_pct) cpu_avg, max(m.memory_pct) mem_max
           FROM service_metrics m JOIN services sv ON sv.id = m.service_id WHERE m.run_id = $1 GROUP BY sv.id ORDER BY sv.kind, sv.name`, [runId], tsPool),
  ]);
  const infra = await infraAggregates(runId);
  const approx = s?.percentile_method === 'interval_weighted_approx';
  const slaEval = sla.filter((x) => x.status !== 'NO_DATA');
  const slaCount = (st: string) => sla.filter((x) => x.status === st).length;
  const slaPassed = slaEval.filter((x) => x.status !== 'FAIL').length;
  const slaPct = slaEval.length ? (slaPassed / slaEval.length) * 100 : n(s?.sla_pass_pct);
  const regressionsOnly = regs.filter((g) => g.direction === 'REGRESSION');
  const improvements = regs.filter((g) => g.direction !== 'REGRESSION');
  const bottlenecks = ((run.analysis?.bottlenecks ?? []) as any[]).filter((b) => b && b.component);
  const topBott = bottlenecks.find((b) => b.confidence >= 0.45);
  const users = n(s?.users_peak) ?? n(run.virtual_users) ?? n(run.cfg_users);
  const targetTps = n(run.target_tps) ?? n(run.cfg_target_tps);
  const durationSec = n(s?.duration_sec) ?? (run.started_at && run.ended_at ? (new Date(run.ended_at).getTime() - new Date(run.started_at).getTime()) / 1000 : null);
  const bd = run.result_breakdown?.breakdown ?? {};
  const st = (k: string) => (bd[k] && bd[k] !== 'N/A' ? bd[k] : null);
  const totalFailures = n(s?.failure_count) ?? errTypes.reduce((a, x) => a + x.n, 0);

  // Time series (whole run) — one query; bucketed to ≤150 points
  let series: Awaited<ReturnType<typeof runSeries>> | null = null;
  try { series = await runSeries(runId, { maxPoints: 150 }); if (series.points.length < 2) series = null; } catch { series = null; }
  const seriesApprox = series?.percentileMethod === 'interval_weighted_approx';

  // Capacity / headroom estimate (only when the model can support it)
  let capacity: Awaited<ReturnType<typeof capacityModel>> | null = null;
  try { capacity = await capacityModel({ orgId: run.organization_id, projectId: run.project_id, testId: run.test_id, environmentId: run.environment_id }); } catch { capacity = null; }

  const sections: Section[] = [];

  /* 1 — Executive summary */
  const resultWord = (run.result ?? 'PENDING').replace(/_/g, ' ').toLowerCase();
  const paragraphs: string[] = [];
  paragraphs.push(`We ran the ${String(run.test_type ?? 'load').toLowerCase()} test “${run.test_name}” against ${run.application_name} in the ${run.environment_name} environment`
    + `${run.build_number ? ` (build ${run.build_number}${run.release_version ?? run.version ? `, version ${run.release_version ?? run.version}` : ''})` : ''}`
    + `${users != null ? ` with up to ${fmtInt(users)} virtual users` : ''}${durationSec != null ? ` for ${fmtDur(durationSec)}` : ''}${targetTps != null ? `, targeting ${fmtNum(targetTps, 1)} TPS` : ''}.`);
  if (s) {
    paragraphs.push(`The run finished with the result ${resultWord.toUpperCase()}${run.performance_score != null ? ` and a performance score of ${Math.round(run.performance_score)}/100` : ''}. `
      + `It processed ${fmtInt(n(s.total_samples))} requests at ${fmtNum(n(s.tps_avg), 1)} TPS on average (peak ${fmtNum(n(s.tps_peak), 1)} TPS), with a 95th-percentile response time of ${approx ? '≈' : ''}${fmtMs(n(s.p95))} and an error rate of ${fmtNum(n(s.error_pct), 2)}%.`);
  } else paragraphs.push('No summary metrics are stored for this run; it may still be analysing or have recorded no samples.');
  const findings: SummaryData['findings'] = [];
  const failed = sla.filter((x) => x.status === 'FAIL');
  if (failed.length) findings.push({ tone: 'fail', text: `${plural(failed.length, 'SLA rule')} failed — worst: ${slaRuleName(failed[0])}${failed[0].transaction ? ` (${failed[0].transaction})` : ''} measured ${fmtNum(n(failed[0].actual_value), 2)}${failed[0].unit ? ' ' + failed[0].unit : ''}.` });
  if (regressionsOnly.length) { const g = regressionsOnly[0]; findings.push({ tone: g.severity === 'CRITICAL' ? 'fail' : 'warn', text: `${plural(regressionsOnly.length, 'regression')} against baseline ${baseline?.runKey ?? ''} — largest: ${g.transaction ?? g.scope} ${metricName(g.metric)} ${fmtSigned(n(g.change_pct), 1)}%.` }); }
  if (targetTps != null && s?.tps_avg != null && n(s.tps_avg)! < targetTps * 0.95) findings.push({ tone: 'warn', text: `Average throughput ${fmtNum(n(s.tps_avg), 1)} TPS stayed below the ${fmtNum(targetTps, 1)} TPS target (${fmtNum(pctOf(n(s.tps_avg), targetTps), 0)}% of target).` });
  if (topBott) findings.push({ tone: topBott.confidence >= 0.65 ? 'warn' : null, text: `${topBott.label}: ${topBott.component} (${Math.round(topBott.confidence * 100)}% confidence).` });
  for (const i of insights.filter((x) => x.severity !== 'INFO')) if (findings.length < 3) findings.push({ tone: i.severity === 'CRITICAL' ? 'fail' : 'warn', text: `${i.title}.` });
  if (findings.length < 3 && slaEval.length && !failed.length) findings.push({ tone: 'pass', text: `All ${plural(slaEval.length, 'evaluated SLA rule')} passed${slaCount('WARNING') ? ` (${slaCount('WARNING')} with warnings)` : ''}.` });
  if (findings.length < 3 && baseline && !regressionsOnly.length) findings.push({ tone: 'pass', text: `No regressions against baseline ${baseline.runKey}${improvements.length ? `; ${plural(improvements.length, 'metric')} improved` : ''}.` });
  if (findings.length < 3 && s && n(s.error_pct)! < 1) findings.push({ tone: 'pass', text: `Error rate stayed low at ${fmtNum(n(s.error_pct), 2)}%.` });
  const recSeen = new Set<string>();
  const recommendations = recs.filter((x) => (recSeen.has(x.title) ? false : (recSeen.add(x.title), true))).slice(0, 3).map((x) => ({ text: `${x.title}: ${x.description}`, priority: x.priority }));
  const risk: SummaryData['risk'] = run.result === 'FAIL' || regressionsOnly.some((g) => g.severity === 'CRITICAL')
    ? { level: 'HIGH', reason: run.result === 'FAIL' ? `The run failed (${(run.result_breakdown?.reasons ?? []).slice(0, 3).join('; ') || 'see result breakdown'}).` : 'Critical regressions were detected against the baseline.' }
    : run.result === 'PASS_WITH_WARNINGS' || failed.length || regressionsOnly.length
      ? { level: 'MEDIUM', reason: `Passed with warnings${(run.result_breakdown?.reasons ?? []).length ? `: ${run.result_breakdown.reasons.slice(0, 3).join('; ')}` : ''}.` }
      : run.result === 'PASS' ? { level: 'LOW', reason: 'All result dimensions passed.' } : { level: 'MEDIUM', reason: 'The result is inconclusive or still pending.' };
  sections.push(chapter('ch-summary', 'Executive summary', 'Outcome of the run in plain language, the most important findings and what to do next.'));
  sections.push({ id: 'summary', title: 'Overview', kind: 'summary', data: { paragraphs, findings: findings.slice(0, 3), recommendations, risk } satisfies SummaryData });

  const kpi = (label: string, key: string, unit: string, better: Kpi['better'], status?: string | null, pctile = false, hint?: string): Kpi => {
    const cur = n(s?.[key]);
    const base = n(baseSummary?.[key]);
    return { label, value: r2(cur, unit === '%' ? 2 : 1), unit, better, status: status ?? null, baseline: baseline ? r2(base) : undefined, deltaPct: r2(delta(cur, base), 1), approx: pctile && approx ? true : undefined, hint };
  };
  sections.push({
    id: 'kpis', title: baseline ? `Key metrics vs baseline ${baseline.runKey}` : 'Key metrics', kind: 'kpis', data: [
      kpi('Requests', 'total_samples', '', 'neutral', null, false, totalFailures ? `${fmtInt(totalFailures)} failed` : undefined),
      kpi('Avg throughput', 'tps_avg', 'TPS', 'higher', st('TPS'), false, targetTps != null ? `target ${fmtNum(targetTps, 1)}` : undefined),
      kpi('Peak throughput', 'tps_peak', 'TPS', 'higher'),
      kpi('Avg response', 'avg_rt', 'ms', 'lower'),
      kpi('P90', 'p90', 'ms', 'lower', null, true), kpi('P95', 'p95', 'ms', 'lower', st('P95'), true), kpi('P99', 'p99', 'ms', 'lower', null, true),
      kpi('Error rate', 'error_pct', '%', 'lower', st('Error Rate')),
      kpi('Peak users', 'users_peak', '', 'neutral'),
      { label: 'SLA compliance', value: slaPct != null ? r2(slaPct, 1) : null, unit: '%', status: st('SLA'), better: 'higher', hint: slaEval.length ? `${slaPassed}/${slaEval.length} rules` : 'no SLA profile' },
      { label: 'Performance score', value: n(run.performance_score) == null ? null : Math.round(run.performance_score), unit: '/100', better: 'higher', status: null },
      { label: 'Regressions', value: baseline ? regressionsOnly.length : null, status: !baseline ? null : regressionsOnly.some((g) => g.severity === 'CRITICAL') ? 'FAIL' : regressionsOnly.length ? 'WARNING' : 'PASS', better: 'lower', hint: baseline ? `vs ${baseline.runKey}` : 'no baseline' },
    ] satisfies Kpi[],
  });
  if (run.result_breakdown || run.score_breakdown) {
    const rows: Record<string, unknown>[] = Object.entries(bd).map(([dim, v]) => ({ dimension: dim, status: v, score: null, weight: null, detail: (run.result_breakdown?.reasons ?? []).filter((x: string) => x.startsWith(dim)).join('; ') }));
    for (const f of run.score_breakdown?.factors ?? []) rows.push({ dimension: `Score — ${f.label}`, status: null, score: f.score != null ? Math.round(f.score) : null, weight: f.weight ?? null, detail: f.detail ?? '' });
    sections.push(table('result', 'Result & score breakdown', [col('dimension', 'Dimension'), col('status', 'Status', 'status'), col('score', 'Score', 'int', '/100'), col('weight', 'Weight', 'int'), col('detail', 'Detail')], rows,
      'Each dimension is classified PASS / WARNING / FAIL from the stored thresholds; the score factors are weighted into the 0–100 performance score.'));
  }

  /* 2 — Configuration & environment */
  sections.push(chapter('ch-config', 'Test configuration & environment', 'What was executed, where, with which load profile and against which baseline, and where the data comes from.'));
  sections.push(kv('identity', 'Run & build', [
    ['Run ID', run.run_key], ['Status', run.status], ['Test', run.test_name], ['Test type', run.test_type], ['Project', run.project_name], ['Application', run.application_name],
    ['Build', run.build_number ?? '—'], ['Version / release', run.release_version ? `${run.release_version}${run.release_name ? ` (${run.release_name})` : ''}` : run.version ?? '—'],
    ['Branch', run.branch ?? '—'], ['Commit', run.commit_sha ? String(run.commit_sha).slice(0, 12) : '—'], ['Triggered by', `${run.triggered_by}${run.ci_system ? ` (${run.ci_system})` : ''}`],
    ['Tester', run.tester ?? '—'], ['Load engine', run.load_engine], ['Execution ID', run.execution_id ?? '—'],
    ['Started', iso(run.started_at) ?? '—'], ['Ended', iso(run.ended_at) ?? '—'],
  ]));
  sections.push(kv('load', 'Load profile', [
    ['Virtual users (configured)', n(run.virtual_users) ?? n(run.cfg_users) ?? '—'], ['Virtual users (peak observed)', n(s?.users_peak) ?? '—'],
    ['Average active users', s?.users_avg != null ? r2(s.users_avg, 1) : '—'], ['Ramp-up', run.ramp_up_sec != null ? fmtDur(n(run.ramp_up_sec)) : '—'],
    ['Ramp-down', run.ramp_down_sec != null ? fmtDur(n(run.ramp_down_sec)) : '—'], ['Planned duration', run.cfg_duration != null ? fmtDur(n(run.cfg_duration)) : '—'],
    ['Measured duration', durationSec != null ? fmtDur(durationSec) : '—'], ['Target TPS', targetTps ?? '—'],
    ['Think time', run.think_time_ms != null ? `${fmtInt(n(run.think_time_ms))} ms` : '—'], ['Thread group', run.thread_group ?? '—'],
    ['Configuration version', run.cfg_version != null ? `v${run.cfg_version}` : '—'], ['SLA profile', run.sla_profile_name ?? 'None'],
  ], run.ramp_up_sec == null && run.cfg_duration == null ? 'No test configuration is stored for this run; observed values come from the measured data.' : undefined));
  sections.push(kv('environment', 'Environment & baseline', [
    ['Environment', `${run.environment_name}${run.environment_type ? ` (${run.environment_type})` : ''}`], ['Servers monitored', servers.length || '—'],
    ['Baseline run', baseline ? baseline.runKey : 'None'], ['Baseline chosen by', baseline ? baseline.reason : '—'],
    ['Primary data source', s ? SOURCE_LABEL[s.source] ?? s.source : '—'], ['Percentile method', s?.percentile_method ? METHOD_LABEL[s.percentile_method] ?? s.percentile_method : '—'],
  ]));
  if (servers.length) sections.push(table('server-inventory', 'Servers', [col('name', 'Server'), col('role', 'Role'), col('host', 'Host', 'mono'), col('cores', 'vCPU', 'int'), col('memory', 'Memory', 'num1', 'GB')],
    servers.map((x) => ({ name: x.name, role: x.role ?? '—', host: x.hostname ?? '—', cores: n(x.cpu_cores), memory: x.memory_mb != null ? r2(x.memory_mb / 1024, 1) : null }))));
  const rec = await reconcile(runId);
  sections.push(table('sources', 'Data sources', [col('source', 'Source'), col('samples', 'Samples', 'int'), col('duration', 'Duration'), col('method', 'Percentiles'), col('computed', 'Computed', 'date'), col('role', 'Used as')],
    sources.map((x, i) => ({ source: SOURCE_LABEL[x.source] ?? x.source, samples: n(x.total_samples), duration: fmtDur(n(x.duration_sec)), method: METHOD_LABEL[x.percentile_method] ?? x.percentile_method ?? '—', computed: iso(x.computed_at), role: i === 0 ? 'Primary' : 'Cross-check' })),
    sources.length ? 'The primary source (live listener > JTL > import > HTML report) feeds every figure in this report.' : 'No summarised data source is stored for this run.'));
  if (rec.status !== 'NOT_AVAILABLE') {
    sections.push(table('reconciliation', `Reconciliation: ${SOURCE_LABEL[rec.liveSource ?? ''] ?? rec.liveSource} vs JMeter HTML report`,
      [col('metric', 'Metric'), col('live', SOURCE_LABEL[rec.liveSource ?? ''] ?? 'Live', 'num'), col('report', 'HTML report', 'num'), col('diff', 'Difference', 'delta', '%'), col('status', 'Status', 'status')],
      (rec.rows as any[]).map((x) => ({ metric: x.unit ? `${x.metric} (${x.unit})` : x.metric, live: r2(x.live), report: r2(x.report), diff: r2(x.differencePct, 2), status: x.status })),
      `Overall: ${rec.status.replace(/_/g, ' ')}. ${(rec as any).notes?.join(' ') ?? ''}`));
  }

  /* 3 — Results over time */
  sections.push(chapter('ch-time', 'Results over time', `How throughput, response time, errors and concurrency evolved during the run${series ? ` (${fmtDur(series.step)} buckets)` : ''}.`));
  if (series) {
    const pts = series.points;
    const p95Rule = sla.find((x) => x.metric === 'p95' && x.scope === 'RUN');
    sections.push(chart('chart-tps', 'Throughput', { type: 'line', unit: 'TPS', yLabel: 'Transactions / s', xType: 'time', series: [{ name: 'Throughput', data: pts.map((p) => [p.t, r2(p.tps)]) }],
      thresholds: targetTps != null ? [{ label: `Target ${fmtNum(targetTps, 1)} TPS`, value: targetTps }] : undefined }));
    if (pts.some((p) => p.users != null)) sections.push(chart('chart-users', 'Active virtual users', { type: 'line', unit: 'users', yLabel: 'Users', xType: 'time', series: [{ name: 'Active users', data: pts.map((p) => [p.t, p.users]) }] }));
    sections.push(chart('chart-latency', 'Response time percentiles', {
      type: 'line', unit: 'ms', yLabel: 'Response time (ms)', xType: 'time', series: [
        { name: 'P50', data: pts.map((p) => [p.t, r2(p.p50, 0)]), style: 'dotted' }, { name: 'P90', data: pts.map((p) => [p.t, r2(p.p90, 0)]), style: 'dashed' },
        { name: 'P95', data: pts.map((p) => [p.t, r2(p.p95, 0)]) }, { name: 'P99', data: pts.map((p) => [p.t, r2(p.p99, 0)]), style: 'dashed' },
      ],
      thresholds: p95Rule && (p95Rule.critical_value ?? p95Rule.warning_value) != null ? [{ label: `P95 SLA ${fmtNum(n(p95Rule.critical_value ?? p95Rule.warning_value), 0)} ms`, value: n(p95Rule.critical_value ?? p95Rule.warning_value)!, status: 'FAIL' }] : undefined,
    }, seriesApprox ? 'Per-bucket percentiles are interval-weighted approximations (≈).' : undefined));
    sections.push(chart('chart-errors', 'Error rate', { type: 'line', unit: '%', yLabel: 'Errors (%)', xType: 'time', series: [{ name: 'Error rate', data: pts.map((p) => [p.t, r2(p.errorPct, 2)]) }] }));
  } else sections.push({ id: 'no-series', title: 'Time series', kind: 'text', data: 'No time-series buckets are stored for this run, so over-time charts cannot be drawn. The aggregate tables in the following chapters are still complete.' });

  /* 4 — Response times & transactions */
  sections.push(chapter('ch-rt', 'Response times & transactions', 'Distribution of response times for the whole run and statistics for every transaction.'));
  if (s) {
    const ladder: [string, number | null][] = [['Min', n(s.min_rt)], ['P50', n(s.p50 ?? s.median_rt)], ['P75', n(s.p75)], ['P90', n(s.p90)], ['P95', n(s.p95)], ['P99', n(s.p99)], ['P99.9', n(s.p999)], ['Max', n(s.max_rt)]];
    sections.push(table('percentiles', 'Response-time distribution', [col('stat', 'Statistic'), col('value', 'Value', 'num', 'ms'), col('base', 'Baseline', 'num', 'ms'), col('change', 'Change', 'delta', '%')],
      [['Average', n(s.avg_rt), n(baseSummary?.avg_rt)], ['Std-dev', n(s.stddev_rt), n(baseSummary?.stddev_rt)],
        ...ladder.map(([k, v]) => [k, v, n(baseSummary?.[{ Min: 'min_rt', P50: 'p50', P75: 'p75', P90: 'p90', P95: 'p95', P99: 'p99', 'P99.9': 'p999', Max: 'max_rt' }[k]!])] as [string, number | null, number | null])]
        .map(([stat, v, b]) => ({ stat: `${approx && /^P\d/.test(stat as string) ? '≈ ' : ''}${stat}`, value: r2(v, 1), base: baseline ? r2(b, 1) : null, change: r2(delta(v as number | null, b as number | null), 1) })),
      `${baseline ? `Baseline = ${baseline.runKey}. ` : ''}${approx ? 'Percentiles marked ≈ are interval-weighted approximations.' : ''}`.trim() || undefined));
    const lad = ladder.filter(([k, v]) => v != null && k !== 'Min');
    if (lad.length > 2) sections.push(chart('chart-ladder', 'Percentile ladder', { type: 'bar', unit: 'ms', xType: 'category', series: [{ name: 'Response time', data: lad.map(([k, v]) => [`${approx && k.startsWith('P') ? '≈' : ''}${k}`, r2(v, 0)]) }] }));
  }
  const txApprox = txns.some((t) => t.percentile_method === 'interval_weighted_approx');
  const TX_LIMIT = 60;
  sections.push(table('transactions', `All transactions (${txns.length})`, [
    col('name', 'Transaction'), col('samples', 'Samples', 'int'), col('errors', 'Errors', 'int'), col('errorPct', 'Err', 'pct', '%'), col('tps', 'TPS', 'num'), col('avg', 'Avg', 'int', 'ms'),
    col('min', 'Min', 'int', 'ms'), col('max', 'Max', 'int', 'ms'), col('p50', 'P50', 'int', 'ms', txApprox), col('p90', 'P90', 'int', 'ms', txApprox), col('p95', 'P95', 'int', 'ms', txApprox),
    col('p99', 'P99', 'int', 'ms', txApprox), col('sd', 'SD', 'int', 'ms'), col('sla', 'SLA', 'status'),
  ], txns.slice(0, TX_LIMIT).map((t) => ({ name: t.name, samples: n(t.samples), errors: n(t.errors), errorPct: r2(t.error_pct), tps: r2(t.tps), avg: r2(t.avg_rt, 0), min: r2(t.min_rt, 0), max: r2(t.max_rt, 0), p50: r2(t.median_rt, 0), p90: r2(t.p90, 0), p95: r2(t.p95, 0), p99: r2(t.p99, 0), sd: r2(t.stddev_rt, 0), sla: t.sla_status && t.sla_status !== 'NO_SLA' ? t.sla_status : null })),
  txns.length > TX_LIMIT ? `Showing the ${TX_LIMIT} highest-volume of ${txns.length} transactions; the Excel and CSV exports contain the same rows. SD = standard deviation.` : txns.length ? 'Sorted by volume. SD = standard deviation of response time.' : 'No transaction statistics are stored for this run.'));

  // Top-N slowest / highest-error with per-transaction trend sparks (bounded: 5 + 5 small queries)
  const slow = [...txns].filter((t) => t.p95 != null).sort((a, b) => b.p95 - a.p95).slice(0, 5);
  const errTop = [...txns].filter((t) => n(t.errors)! > 0).sort((a, b) => b.error_pct - a.error_pct || b.errors - a.errors).slice(0, 5);
  const sparks = new Map<string, { p95: (number | null)[]; err: (number | null)[] }>();
  if (series) {
    await Promise.all([...new Set([...slow, ...errTop].map((t) => t.name))].map(async (name) => {
      try { const ts = await runSeries(runId, { transaction: name, maxPoints: 40, source: s?.source }); sparks.set(name, { p95: ts.points.map((p) => r2(p.p95, 0)), err: ts.points.map((p) => r2(p.errorPct, 2)) }); } catch { /* spark optional */ }
    }));
  }
  if (slow.length) {
    sections.push(chart('chart-slowest', 'Slowest transactions (P95)', { type: 'bar', unit: 'ms', xType: 'category', series: [{ name: 'P95', data: slow.map((t) => [t.name, r2(t.p95, 0)]) }, { name: 'Average', data: slow.map((t) => [t.name, r2(t.avg_rt, 0)]) }] }));
    sections.push(table('slowest', 'Top 5 slowest transactions', [col('name', 'Transaction'), col('samples', 'Samples', 'int'), col('avg', 'Avg', 'int', 'ms'), col('p95', 'P95', 'int', 'ms', txApprox), col('p99', 'P99', 'int', 'ms', txApprox), col('max', 'Max', 'int', 'ms'), col('trend', 'P95 over time', 'spark')],
      slow.map((t) => ({ name: t.name, samples: n(t.samples), avg: r2(t.avg_rt, 0), p95: r2(t.p95, 0), p99: r2(t.p99, 0), max: r2(t.max_rt, 0), trend: sparks.get(t.name)?.p95 ?? null }))));
  }
  if (errTop.length) sections.push(table('error-txns', 'Top 5 transactions by error rate', [col('name', 'Transaction'), col('samples', 'Samples', 'int'), col('errors', 'Errors', 'int'), col('errorPct', 'Error rate', 'pct', '%'), col('trend', 'Errors over time', 'spark')],
    errTop.map((t) => ({ name: t.name, samples: n(t.samples), errors: n(t.errors), errorPct: r2(t.error_pct), trend: sparks.get(t.name)?.err ?? null }))));

  /* 5 — Errors */
  sections.push(chapter('ch-errors', 'Errors', totalFailures ? `${fmtInt(totalFailures)} failed requests (${fmtNum(n(s?.error_pct), 2)}% of all requests), broken down by response code, type, message and transaction.` : 'No failed requests were recorded during this run.'));
  sections.push({ id: 'error-kpis', title: 'Error overview', kind: 'kpis', data: [
    { label: 'Failed requests', value: totalFailures, status: st('Error Rate') }, { label: 'Error rate', value: r2(s?.error_pct), unit: '%', status: st('Error Rate') },
    { label: 'Error types', value: errTypes.length }, { label: 'Transactions with errors', value: txns.filter((t) => n(t.errors)! > 0).length, hint: `of ${txns.length}` },
  ] satisfies Kpi[] });
  const codeTotal = codes.reduce((a, x) => a + Number(x.n), 0);
  if (codes.length) sections.push(table('codes', 'Responses by status code', [col('code', 'Response code', 'mono'), col('count', 'Responses', 'int'), col('share', 'Share', 'pct', '%'), col('failed', 'Failed samples', 'int'), col('failPct', 'Failed', 'pct', '%')],
    codes.map((x) => ({ code: x.response_code, count: Number(x.n), share: r2(pctOf(Number(x.n), codeTotal), 2), failed: Number(x.failed ?? 0), failPct: r2(pctOf(Number(x.failed ?? 0), Number(x.n)), 2) })),
    'Failed samples include assertion failures on otherwise successful HTTP codes (e.g. 200 with an unexpected body).'));
  const typeTotal = errTypes.reduce((a, x) => a + x.n, 0);
  if (errTypes.length) {
    sections.push(table('error-types', 'Errors by type', [col('type', 'Type'), col('count', 'Errors', 'int'), col('share', 'Share', 'pct', '%')], errTypes.map((x) => ({ type: x.error_type, count: x.n, share: r2(pctOf(x.n, typeTotal), 1) }))));
    sections.push(table('error-messages', 'Top error messages', [col('type', 'Type'), col('code', 'Code', 'mono'), col('message', 'Message'), col('txns', 'Txns', 'int'), col('count', 'Errors', 'int'), col('share', 'Share', 'pct', '%'), col('first', 'First seen', 'date')],
      errGroups.map((e) => ({ type: e.error_type, code: e.response_code || '—', message: String(e.message ?? '').slice(0, 180) || '—', txns: e.txns, count: e.n, share: r2(pctOf(e.n, typeTotal), 1), first: iso(e.first_ts) }))));
  }
  const txErr = txns.filter((t) => n(t.errors)! > 0).sort((a, b) => b.errors - a.errors).slice(0, 15);
  if (txErr.length) sections.push(table('error-by-txn', 'Errors by transaction', [col('name', 'Transaction'), col('errors', 'Errors', 'int'), col('samples', 'Samples', 'int'), col('errorPct', 'Error rate', 'pct', '%'), col('share', 'Share of errors', 'pct', '%')],
    txErr.map((t) => ({ name: t.name, errors: n(t.errors), samples: n(t.samples), errorPct: r2(t.error_pct), share: r2(pctOf(n(t.errors), totalFailures), 1) }))));
  if (series && series.points.some((p) => p.errors > 0)) sections.push(chart('chart-error-timeline', 'Error timeline', { type: 'line', unit: 'errors', yLabel: 'Failed requests per bucket', xType: 'time', series: [{ name: 'Failed requests', data: series.points.map((p) => [p.t, p.errors]) }] }));

  /* 6 — SLA */
  sections.push(chapter('ch-sla', 'SLA evaluation', sla.length ? `${run.sla_profile_name ? `Profile “${run.sla_profile_name}”: ` : ''}${slaCount('PASS')} passed, ${slaCount('WARNING')} warning, ${slaCount('FAIL')} failed${slaCount('NO_DATA') ? `, ${slaCount('NO_DATA')} without data` : ''}.` : 'No SLA profile was attached to this test, so no rules were evaluated.'));
  if (sla.length) {
    sections.push({ id: 'sla-kpis', title: 'Compliance', kind: 'kpis', data: [
      { label: 'Compliance', value: r2(slaPct, 1), unit: '%', status: st('SLA') }, { label: 'Passed', value: slaCount('PASS'), status: slaCount('PASS') ? 'PASS' : null },
      { label: 'Warnings', value: slaCount('WARNING'), status: slaCount('WARNING') ? 'WARNING' : null }, { label: 'Failed', value: slaCount('FAIL'), status: slaCount('FAIL') ? 'FAIL' : null },
    ] satisfies Kpi[] });
    sections.push(table('sla', 'Rule-by-rule results', [col('rule', 'Rule'), col('scope', 'Scope'), col('dir', 'Dir'), col('warning', 'Warning', 'num'), col('critical', 'Critical', 'num'), col('actual', 'Actual', 'num'), col('unit', 'Unit'), col('margin', 'Margin', 'delta', '%'), col('status', 'Status', 'status')],
      sla.map((x) => ({ rule: slaRuleName(x), scope: x.transaction ? x.transaction : 'Whole run', dir: x.direction === 'HIGHER' ? '≥' : '≤', warning: r2(x.warning_value), critical: r2(x.critical_value), actual: r2(x.actual_value), unit: x.unit ?? '', margin: r2(slaMargin(n(x.actual_value), n(x.warning_value), n(x.critical_value), x.direction), 1), status: x.status })),
      'Margin = distance to the limit (critical, else warning) as % of the limit; negative = limit exceeded. ≤ means lower is better.'));
  }

  /* 7 — Baseline comparison */
  sections.push(chapter('ch-baseline', 'Baseline comparison', baseline ? `Compared with ${baseline.runKey} (${baseline.reason}). Changes under 2% are neutral.` : 'No baseline is available — set a baseline run on the test, or run it again to compare with the previous completed run.'));
  if (baseline) {
    const cmp = await compareRuns([baseline.id, runId]);
    sections.push(table('baseline', 'Key metric deltas', [col('metric', 'Metric'), col('baseline', baseline.runKey, 'num'), col('current', run.run_key, 'num'), col('change', 'Change', 'delta', '%'), col('verdict', 'Direction', 'status')],
      cmp.metrics.map((m) => ({ metric: metricLabel(m), baseline: r2(m.values[0]), current: r2(m.values[1]), change: r2(m.changes[1], 1), verdict: m.verdicts[1] === 'neutral' ? null : m.verdicts[1] }))));
    const txd = cmp.transactions.map((t) => ({ name: t.name, b: r2(t.p95[0], 0), c: r2(t.p95[1], 0), ch: r2(t.p95Change[1], 1), ab: r2(t.avg[0], 0), ac: r2(t.avg[1], 0), eb: r2(t.errorPct[0]), ec: r2(t.errorPct[1]) }))
      .filter((t) => t.b != null || t.c != null).sort((a, b) => Math.abs(b.ch ?? 0) - Math.abs(a.ch ?? 0));
    if (txd.length) sections.push(table('baseline-txns', 'Transaction deltas (largest P95 change first)', [col('name', 'Transaction'), col('ab', 'Avg base', 'int', 'ms'), col('ac', 'Avg now', 'int', 'ms'), col('b', 'P95 base', 'int', 'ms'), col('c', 'P95 now', 'int', 'ms'), col('ch', 'P95 Δ', 'delta', '%'), col('eb', 'Err base', 'pct', '%'), col('ec', 'Err now', 'pct', '%'), col('verdict', 'Direction', 'status')],
      txd.slice(0, 40).map((t) => ({ ...t, verdict: t.ch == null || Math.abs(t.ch) < 2 ? null : t.ch > 0 ? 'worse' : 'better' })), txd.length > 40 ? `Showing 40 of ${txd.length} transactions.` : undefined));
    sections.push(table('regressions', 'Detected regressions & improvements', [col('direction', 'Type', 'status'), col('severity', 'Severity', 'status'), col('scope', 'Scope'), col('metric', 'Metric'), col('previous', 'Baseline', 'num'), col('current', 'Current', 'num'), col('change', 'Change', 'delta', '%'), col('threshold', 'Threshold', 'num', '%'), col('impact', 'Likely related to')],
      regs.slice(0, 40).map((g) => ({ direction: g.direction, severity: g.severity, scope: g.transaction ?? g.scope, metric: metricName(g.metric), previous: r2(g.previous_value), current: r2(g.current_value), change: r2(g.change_pct, 1), threshold: r2(g.threshold_pct, 0), impact: (g.likely_impacted ?? []).join(', ') || '—' })),
      regs.length ? 'Severity reflects the size of the change relative to the configured threshold; "likely related to" lists bottleneck candidates with ≥45% confidence at detection time.' : 'No significant changes versus the baseline.'));
  }

  /* 8 — Infrastructure */
  const hasInfra = infra.hasServer || infra.hasLoadgen || infra.hasJvm || infra.hasDb || services.length > 0;
  sections.push(chapter('ch-infra', 'Infrastructure', hasInfra ? 'Resource utilisation of the monitored servers, JVMs, databases and services while the load was applied.' : 'No infrastructure, JVM, database or service metrics were collected for this run.'));
  if (hasInfra) {
    const ik: Kpi[] = [];
    if (infra.hasServer) ik.push({ label: 'CPU avg / max', value: `${fmtNum(infra.cpuAvg, 0)} / ${fmtNum(infra.cpuMax, 0)}`, unit: '%', status: st('CPU') }, { label: 'Memory max', value: r2(infra.memMax, 1), unit: '%' }, { label: 'Disk max', value: r2(infra.diskMax, 1), unit: '%' });
    if (infra.hasLoadgen) ik.push({ label: 'Load generator CPU max', value: r2(infra.loadgenCpuMax, 1), unit: '%', status: infra.loadgenCpuMax != null && infra.loadgenCpuMax > 85 ? 'WARNING' : null });
    if (infra.hasJvm) ik.push({ label: 'Heap max', value: r2(infra.heapPctMax, 1), unit: '%' }, { label: 'GC pause max', value: r2(infra.gcPauseMax, 0), unit: 'ms' });
    if (infra.hasDb) ik.push({ label: 'DB latency avg', value: r2(infra.dbLatencyAvg, 1), unit: 'ms' }, { label: 'DB pool max', value: r2(infra.dbPoolPctMax, 1), unit: '%' });
    sections.push({ id: 'infra-kpis', title: 'Utilisation summary', kind: 'kpis', data: ik });
    if (servers.length) sections.push(table('servers', 'Servers', [col('name', 'Server'), col('role', 'Role'), col('cpuAvg', 'CPU avg', 'num1', '%'), col('cpuP95', 'CPU P95', 'num1', '%'), col('cpuMax', 'CPU max', 'num1', '%'), col('memAvg', 'Mem avg', 'num1', '%'), col('memMax', 'Mem max', 'num1', '%'), col('diskMax', 'Disk max', 'num1', '%'), col('netIn', 'Net in', 'num1', 'KB/s'), col('netOut', 'Net out', 'num1', 'KB/s'), col('load', 'Load 1m', 'num')],
      servers.map((x) => ({ name: x.name, role: x.role ?? '—', cpuAvg: r2(x.cpu_avg, 1), cpuP95: r2(x.cpu_p95, 1), cpuMax: r2(x.cpu_max, 1), memAvg: r2(x.mem_avg, 1), memMax: r2(x.mem_max, 1), diskMax: r2(x.disk_max, 1), netIn: x.net_in != null ? r2(x.net_in / 1024, 1) : null, netOut: x.net_out != null ? r2(x.net_out / 1024, 1) : null, load: r2(x.load_max) }))));
    const step = Math.max(5, Math.ceil((durationSec ?? 600) / 100));
    const nameById = new Map(servers.map((x) => [x.id, `${x.name}${x.role ? ` (${x.role})` : ''}`]));
    try {
      if (servers.length) {
        const srv = await infraSeries('server_metrics', ['cpu_pct', 'memory_pct'], { runId, groupBy: 'server_id', step });
        const ids = [...servers].sort((a, b) => (n(b.cpu_avg) ?? 0) - (n(a.cpu_avg) ?? 0)).slice(0, 6).map((x) => x.id);
        const by = (k: string) => ids.map((id) => ({ name: nameById.get(id) ?? 'server', data: srv.points.filter((p) => p.server_id === id).map((p) => [p.t, r2(p[k], 1)] as [number, number | null]) })).filter((x) => x.data.length > 1);
        const cpuS = by('cpu_pct'), memS = by('memory_pct');
        if (cpuS.length) sections.push(chart('chart-cpu', 'CPU utilisation by server', { type: 'line', unit: '%', yLabel: 'CPU (%)', xType: 'time', series: cpuS }, servers.length > 6 ? 'The 6 busiest servers are shown.' : undefined));
        if (memS.length) sections.push(chart('chart-mem', 'Memory utilisation by server', { type: 'line', unit: '%', yLabel: 'Memory (%)', xType: 'time', series: memS }));
      }
    } catch { /* charts optional */ }
    if (jvms.length) {
      sections.push(table('jvm', 'JVM', [col('name', 'JVM / service'), col('heapSize', 'Heap size', 'int', 'MB'), col('heapAvg', 'Heap avg', 'num1', '%'), col('heapMax', 'Heap max', 'num1', '%'), col('gcPause', 'GC pause max', 'int', 'ms'), col('gcTime', 'GC time avg', 'num1', 'ms'), col('threads', 'Threads max', 'int')],
        jvms.map((x) => ({ name: x.name, heapSize: r2(x.heap_size, 0), heapAvg: r2(x.heap_avg, 1), heapMax: r2(x.heap_max, 1), gcPause: r2(x.gc_pause_max, 0), gcTime: r2(x.gc_time_avg, 1), threads: n(x.threads_max) }))));
      try {
        const js = await infraSeries('jvm_metrics', ['heap_used_mb', 'heap_max_mb'], { runId, groupBy: 'service_id', step });
        const ser = jvms.slice(0, 6).map((j) => ({ name: j.name, data: js.points.filter((p) => p.service_id === j.service_id).map((p) => [p.t, r2(pctOf(n(p.heap_used_mb), n(p.heap_max_mb)), 1)] as [number, number | null]) })).filter((x) => x.data.length > 1);
        if (ser.length) sections.push(chart('chart-heap', 'JVM heap usage', { type: 'line', unit: '%', yLabel: 'Heap used (%)', xType: 'time', series: ser }));
      } catch { /* optional */ }
    }
    if (dbs.length) {
      sections.push(table('databases', 'Databases', [col('name', 'Database'), col('engine', 'Engine'), col('latAvg', 'Latency avg', 'num1', 'ms'), col('latMax', 'Latency max', 'num1', 'ms'), col('act', 'Active conns max', 'int'), col('pool', 'Pool max', 'num1', '%'), col('slow', 'Slow queries', 'int'), col('locks', 'Locks max', 'int'), col('dl', 'Deadlocks', 'int'), col('cpu', 'CPU avg', 'num1', '%')],
        dbs.map((x) => ({ name: x.name, engine: x.engine ?? '—', latAvg: r2(x.lat_avg, 1), latMax: r2(x.lat_max, 1), act: n(x.act_max), pool: r2(x.pool_max, 1), slow: n(x.slow), locks: n(x.locks_max), dl: n(x.deadlocks), cpu: r2(x.cpu_avg, 1) }))));
      try {
        const ds = await infraSeries('database_metrics', ['query_latency_ms'], { runId, step });
        if (ds.points.length > 1) sections.push(chart('chart-db', 'Database query latency', { type: 'line', unit: 'ms', yLabel: 'Latency (ms)', xType: 'time', series: [{ name: 'Average', data: ds.points.map((p) => [p.t, r2(p.query_latency_ms, 1)]) }, { name: 'Max', data: ds.points.map((p) => [p.t, r2(p.query_latency_ms_max, 1)]), style: 'dashed' }] }));
      } catch { /* optional */ }
    }
    if (services.length) sections.push(table('services', 'Services (APM)', [col('name', 'Service'), col('kind', 'Kind'), col('rate', 'Req/s', 'num1'), col('errAvg', 'Err avg', 'pct', '%'), col('errMax', 'Err max', 'pct', '%'), col('lat', 'Latency avg', 'num1', 'ms'), col('p95', 'P95 max', 'num1', 'ms'), col('exc', 'Exceptions', 'int'), col('cpu', 'CPU avg', 'num1', '%')],
      services.map((x) => ({ name: x.name, kind: x.kind, rate: r2(x.rate, 1), errAvg: r2(x.err_avg), errMax: r2(x.err_max), lat: r2(x.lat_avg, 1), p95: r2(x.p95_max, 1), exc: n(x.exceptions), cpu: r2(x.cpu_avg, 1) }))));
  }
  if (bottlenecks.length) {
    sections.push(table('bottlenecks', 'Correlation & bottleneck findings', [col('component', 'Component'), col('label', 'Assessment'), col('confidence', 'Confidence', 'int', '%'), col('corr', 'Correlation', 'num'), col('evidence', 'Evidence')],
      bottlenecks.slice(0, 10).map((b) => ({ component: b.component, label: b.label, confidence: r2((b.confidence ?? 0) * 100, 0), corr: r2(b.correlation, 2), evidence: (b.evidence ?? []).map((e: any) => (typeof e === 'string' ? e : e.text ?? e.description ?? JSON.stringify(e))).slice(0, 3).join('; ') })),
      'Confidence is a correlation-based likelihood (never 100%): ≥80% strong correlation, ≥65% likely, ≥45% possible bottleneck.'));
  }
  const gaps = (run.analysis?.gaps ?? []) as string[];
  if (gaps.length) sections.push({ id: 'gaps', title: 'Evidence gaps', kind: 'list', data: gaps });

  /* 9 — Insights & recommendations */
  sections.push(chapter('ch-insights', 'Insights & recommendations', 'Automated analysis findings with severity and confidence, prioritised actions, and a capacity estimate where the data supports one.'));
  sections.push({ id: 'insights', title: 'Insights', kind: 'findings',
    data: insights.map((i) => ({ severity: i.severity, title: i.title, description: `${i.description}${i.confidence != null && !/confidence/i.test(i.description) ? ` — confidence ${Math.round(i.confidence * 100)}%${i.confidence_label ? ` (${i.confidence_label})` : ''}` : ''}` })) satisfies Finding[],
    note: insights.length ? undefined : 'No insights were generated for this run.' });
  if (recs.length) {
    const seen = new Set<string>();
    sections.push(table('recommendations', 'Recommendations', [col('priority', 'Priority', 'status'), col('category', 'Area'), col('title', 'Recommendation'), col('description', 'Detail')],
      recs.filter((x) => (seen.has(x.title + x.description) ? false : (seen.add(x.title + x.description), true))).map((x) => ({ priority: x.priority, category: String(x.category ?? '').replace(/_/g, ' ').toLowerCase(), title: x.title, description: x.description }))));
  }
  if (capacity) {
    const sat = capacity.estimatedSaturationTps;
    const head = sat != null && s?.tps_avg != null ? ((sat - n(s.tps_avg)!) / sat) * 100 : null;
    sections.push(kv('capacity', 'Capacity & headroom (estimate)', [
      ['Observed average throughput', `${fmtNum(n(s?.tps_avg), 1)} TPS`], ['Estimated saturation', sat != null ? `≈ ${fmtNum(sat, 1)} TPS` : 'Not enough data'],
      ['Estimated headroom', head != null ? `≈ ${fmtNum(head, 0)}% (${fmtSigned(r2(sat! - n(s!.tps_avg)!, 1), 1)} TPS)` : 'n/a'], ['Latency model', capacity.model.description],
      ['Runs used', capacity.observations.length], ['P95 SLA used', capacity.slaP95 != null ? `${fmtNum(capacity.slaP95, 0)} ms` : '—'],
    ], capacity.notes.join(' ')));
  }

  /* 10 — Appendix */
  sections.push(chapter('ch-appendix', 'Appendix', 'Glossary, methodology, attached artifacts and report metadata.'));
  sections.push(kv('glossary', 'Glossary of metrics', GLOSSARY));
  sections.push({ id: 'methodology', title: 'Methodology', kind: 'list', data: methodology(s?.percentile_method) });
  sections.push(table('artifacts', 'Artifacts attached to the run', [col('kind', 'Kind'), col('name', 'Name'), col('version', 'Ver', 'int'), col('size', 'Size', 'num1', 'KB'), col('uploaded', 'Uploaded', 'date'), col('by', 'By'), col('status', 'Processing', 'status')],
    artifacts.map((x) => ({ kind: String(x.kind).replace(/_/g, ' '), name: x.name, version: n(x.current_version), size: x.size_bytes != null ? r2(Number(x.size_bytes) / 1024, 1) : null, uploaded: iso(x.uploaded_at), by: x.uploaded_by_name ?? x.source ?? '—', status: x.processing_status ?? null })),
    artifacts.length ? undefined : 'No artifacts (JTL, HTML report, logs, JMX…) are attached to this run.'));
  sections.push(kv('metadata', 'Report metadata', [['Report type', 'Test execution'], ['Report version', `v${version}`], ['Generated', new Date().toISOString()], ['Run ID', run.run_key], ['Primary data source', s ? SOURCE_LABEL[s.source] ?? s.source : '—'], ['Analysed at', iso(run.analyzed_at) ?? '—']]));

  return {
    title, type: 'TEST_EXECUTION', generatedAt: new Date().toISOString(), version, audience: 'ENGINEERING', schema: 2, confidentiality: CONFIDENTIALITY,
    subject: { runKey: run.run_key, testName: run.test_name, projectName: run.project_name, environment: run.environment_name, build: run.build_number ?? undefined },
    result: { status: run.result ?? 'PENDING', score: n(run.performance_score) == null ? null : Math.round(Number(run.performance_score)), breakdown: bd, reasons: run.result_breakdown?.reasons ?? [] },
    cover: { label: 'Test execution report', facts: [['Run ID', run.run_key], ['Test', `${run.test_name} (${String(run.test_type).toLowerCase()})`], ['Project', `${run.project_name} · ${run.application_name}`], ['Environment', run.environment_name],
      ['Build / version', [run.build_number, run.release_version ?? run.version].filter(Boolean).join(' · ') || '—'], ['Executed', run.started_at ? `${iso(run.started_at)!.slice(0, 16).replace('T', ' ')} UTC${durationSec ? ` · ${fmtDur(durationSec)}` : ''}` : '—'], ['Baseline', baseline?.runKey ?? 'None']] },
    sections,
  };
}

/* ------------------------------------------------------------------ Comparison */

export async function buildComparisonContent(runIds: string[], version: number, title: string): Promise<ReportContent> {
  const cmp = await compareRuns(runIds);
  const runs = await query(`${RUN_SELECT} WHERE r.id = ANY($1::uuid[])`, [runIds]);
  const byId = new Map(runs.map((r) => [r.id, r]));
  const ordered = runIds.map((id) => byId.get(id)).filter(Boolean) as any[];
  const keys = ordered.map((r) => r.run_key);
  const L = (i: number) => String.fromCharCode(65 + i);
  const summaries = await Promise.all(ordered.map((r) => primarySummary(r.id)));
  const anyApprox = summaries.some((x) => x?.percentile_method === 'interval_weighted_approx');
  const sections: Section[] = [];

  const vs = cmp.metrics.flatMap((m) => m.verdicts.map((v, i) => ({ m, v, i, c: m.changes[i] }))).filter((x) => x.i > 0);
  const worse = vs.filter((x) => x.v === 'worse').sort((a, b) => Math.abs(b.c ?? 0) - Math.abs(a.c ?? 0));
  const better = vs.filter((x) => x.v === 'better').sort((a, b) => Math.abs(b.c ?? 0) - Math.abs(a.c ?? 0));
  const regs = await query(`SELECT g.*, r.run_key FROM regressions g JOIN test_runs r ON r.id = g.run_id WHERE g.run_id = ANY($1::uuid[]) AND g.direction = 'REGRESSION'
                            ORDER BY CASE g.severity WHEN 'CRITICAL' THEN 0 WHEN 'WARNING' THEN 1 ELSE 2 END, abs(g.change_pct) DESC NULLS LAST LIMIT 30`, [runIds]);
  const fails = ordered.filter((r) => r.result === 'FAIL');
  const p95 = cmp.metrics.find((m) => m.key === 'p95');
  const findings: SummaryData['findings'] = [];
  for (const w of worse.slice(0, 2)) findings.push({ tone: 'warn', text: `${w.m.label} changed ${fmtSigned(r2(w.c, 1), Math.abs(w.c ?? 0) >= 100 ? 0 : 1)}% in run ${L(w.i)} (${keys[w.i]}) versus the reference.` });
  for (const b of better.slice(0, 3 - findings.length)) findings.push({ tone: 'pass', text: `${b.m.label} improved ${fmtSigned(r2(b.c, 1), Math.abs(b.c ?? 0) >= 100 ? 0 : 1)}% in run ${L(b.i)} (${keys[b.i]}).` });
  if (fails.length && findings.length < 3) findings.push({ tone: 'fail', text: `${plural(fails.length, 'run')} failed: ${fails.map((r) => r.run_key).join(', ')}.` });
  const recs = await query(`SELECT DISTINCT ON (title) title, description, priority FROM recommendations WHERE run_id = $1 ORDER BY title, CASE priority WHEN 'HIGH' THEN 0 WHEN 'MEDIUM' THEN 1 ELSE 2 END`, [runIds[runIds.length - 1]]);
  sections.push(chapter('ch-summary', 'Executive summary', `Side-by-side comparison of ${ordered.length} runs. Run A (${keys[0]}) is the reference for every change %.`));
  sections.push({ id: 'summary', title: 'Overview', kind: 'summary', data: {
    paragraphs: [
      `This report compares ${ordered.length} runs of ${[...new Set(ordered.map((r) => `“${r.test_name}”`))].join(', ')} in ${[...new Set(ordered.map((r) => r.environment_name))].join(', ')}, executed between ${day(ordered.map((r) => r.started_at).filter(Boolean).sort()[0])} and ${day(ordered.map((r) => r.started_at).filter(Boolean).sort().pop())}.`,
      `Across all compared metrics, ${plural(better.length, 'change')} ${better.length === 1 ? 'is an improvement' : 'are improvements'} and ${plural(worse.length, 'change')} ${worse.length === 1 ? 'is a degradation' : 'are degradations'} relative to run A.${p95 ? ` P95 ranged from ${fmtMs(Math.min(...p95.values.filter((v): v is number => v != null)))} to ${fmtMs(Math.max(...p95.values.filter((v): v is number => v != null)))}.` : ''}`,
    ],
    findings: findings.slice(0, 3),
    recommendations: recs.sort((a, b) => sevRank(a.priority) - sevRank(b.priority)).slice(0, 3).map((x) => ({ text: `${x.title}: ${x.description}`, priority: x.priority })),
    risk: fails.length || regs.some((g) => g.severity === 'CRITICAL') ? { level: 'HIGH', reason: fails.length ? `${plural(fails.length, 'compared run')} failed.` : 'Critical regressions are recorded for compared runs.' }
      : worse.length > better.length ? { level: 'MEDIUM', reason: 'More metrics degraded than improved versus the reference.' } : { level: 'LOW', reason: 'No failing runs and no net degradation versus the reference.' },
  } satisfies SummaryData });
  sections.push(table('runs', 'Runs compared', [col('letter', 'Run'), col('runKey', 'Run ID', 'mono'), col('test', 'Test'), col('environment', 'Environment'), col('build', 'Build'), col('users', 'VUs', 'int'), col('duration', 'Duration'), col('started', 'Started', 'date'), col('result', 'Result', 'status'), col('score', 'Score', 'int')],
    ordered.map((r, i) => ({ letter: L(i), runKey: r.run_key, test: r.test_name, environment: r.environment_name, build: r.build_number ?? '—', users: n(summaries[i]?.users_peak) ?? n(r.virtual_users), duration: fmtDur(n(summaries[i]?.duration_sec)), started: iso(r.started_at), result: r.result ?? r.status, score: r.performance_score != null ? Math.round(r.performance_score) : null }))));

  sections.push(chapter('ch-kpis', 'Key metrics side by side', 'Every metric for every run, with the change versus run A and its direction.'));
  const kcols: Column[] = [col('metric', 'Metric'), ...keys.map((k, i) => col(`v${i}`, `${L(i)}`, 'num')), ...keys.slice(1).map((_, j) => col(`c${j + 1}`, `Δ ${L(j + 1)}`, 'delta', '%')), ...(keys.length === 2 ? [col('verdict', 'Direction', 'status')] : [])];
  sections.push(table('metrics', 'All metrics', kcols, cmp.metrics.map((m) => {
    const row: Record<string, unknown> = { metric: `${anyApprox && /^P\d/.test(m.label) ? '≈ ' : ''}${metricLabel(m)}` };
    m.values.forEach((v, i) => { row[`v${i}`] = r2(v); });
    m.changes.forEach((c, i) => { if (i > 0) row[`c${i}`] = r2(c, 1); });
    if (keys.length === 2) row.verdict = m.verdicts[1] === 'neutral' ? null : m.verdicts[1];
    return row;
  }), `Columns A–${L(keys.length - 1)} follow the "Runs compared" table. Δ = change vs A.${anyApprox ? ' ≈ = approximate percentiles in at least one run.' : ''}`));
  const bar = (key: string, t: string, unit: string, d = 0) => { const m = cmp.metrics.find((x) => x.key === key); if (m) sections.push(chart(`chart-${key}`, t, { type: 'bar', unit, xType: 'category', series: [{ name: t, data: keys.map((k, i) => [`${L(i)} · ${k}`, r2(m.values[i], d)]) }] })); };
  bar('p95', 'P95 response time by run', 'ms'); bar('tps', 'Average throughput by run', 'TPS', 1); bar('error_pct', 'Error rate by run', '%', 2);

  // Overlaid time series aligned on elapsed time (bounded: ≤6 runs × 80 points)
  const ser = await Promise.all(ordered.map((r) => runSeries(r.id, { maxPoints: 80 }).catch(() => null)));
  if (ser.filter((x) => x && x.points.length > 1).length >= 2) {
    const over = (f: (p: any) => number | null) => ser.map((x, i) => ({ name: `${L(i)} · ${keys[i]}`, style: (['solid', 'dashed', 'dotted'] as const)[i % 3], data: x && x.points.length ? x.points.map((p) => [(p.t - x.points[0].t) / 60000, f(p)] as [number, number | null]) : [] })).filter((x) => x.data.length > 1);
    sections.push(chart('chart-over-tps', 'Throughput over elapsed time', { type: 'line', unit: 'TPS', yLabel: 'Transactions / s', xType: 'elapsed', series: over((p) => r2(p.tps, 1)) }));
    sections.push(chart('chart-over-p95', 'P95 over elapsed time', { type: 'line', unit: 'ms', yLabel: 'P95 (ms)', xType: 'elapsed', series: over((p) => r2(p.p95, 0)) }, 'Runs are aligned on minutes since their first sample.'));
  }

  sections.push(chapter('ch-txns', 'Transactions', 'Per-transaction deltas across runs, largest change first.'));
  const txRows = cmp.transactions.map((t) => {
    const row: Record<string, unknown> = { name: t.name };
    t.p95.forEach((v, i) => { row[`p${i}`] = r2(v, 0); });
    t.p95Change.forEach((c, i) => { if (i > 0) row[`c${i}`] = r2(c, 1); });
    t.errorPct.forEach((v, i) => { row[`e${i}`] = r2(v); });
    t.avg.forEach((v, i) => { row[`a${i}`] = r2(v, 0); });
    row.maxChange = Math.max(...t.p95Change.filter((c): c is number => c != null).map(Math.abs), 0);
    return row;
  }).sort((a, b) => (b.maxChange as number) - (a.maxChange as number));
  sections.push(table('transactions', 'P95 by transaction', [col('name', 'Transaction'), ...keys.map((_, i) => col(`p${i}`, `P95 ${L(i)}`, 'int', 'ms')), ...keys.slice(1).map((_, j) => col(`c${j + 1}`, `Δ ${L(j + 1)}`, 'delta', '%'))],
    txRows.slice(0, 50).map(({ maxChange, ...r }) => r), txRows.length > 50 ? `Showing 50 of ${txRows.length} transactions.` : undefined));
  sections.push(table('transactions-avg-err', 'Average response time and error rate by transaction', [col('name', 'Transaction'), ...keys.map((_, i) => col(`a${i}`, `Avg ${L(i)}`, 'int', 'ms')), ...keys.map((_, i) => col(`e${i}`, `Err ${L(i)}`, 'pct', '%'))],
    txRows.slice(0, 50).map((r) => { const o: Record<string, unknown> = { name: r.name }; keys.forEach((_, i) => { o[`a${i}`] = r[`a${i}`]; o[`e${i}`] = r[`e${i}`]; }); return o; })));
  if (cmp.endpoints.length) {
    sections.push(table('endpoints', 'API endpoints — average response time', [col('endpoint', 'Endpoint', 'mono'), ...keys.map((_, i) => col(`a${i}`, `Avg ${L(i)}`, 'int', 'ms')), ...keys.slice(1).map((_, j) => col(`c${j + 1}`, `Δ ${L(j + 1)}`, 'delta', '%'))],
      cmp.endpoints.slice(0, 40).map((e) => { const row: Record<string, unknown> = { endpoint: e.endpoint }; e.avg.forEach((v, i) => { row[`a${i}`] = r2(v, 0); }); e.avgChange.forEach((c, i) => { if (i > 0) row[`c${i}`] = r2(c, 1); }); return row; })));
  }

  sections.push(chapter('ch-quality', 'SLA, regressions & risks', 'SLA pass rate per run and the regressions recorded for the compared runs (each against its own baseline).'));
  sections.push(table('sla', 'SLA results by run', [col('runKey', 'Run'), col('PASS', 'Pass', 'int'), col('WARNING', 'Warning', 'int'), col('FAIL', 'Fail', 'int'), col('NO_DATA', 'No data', 'int'), col('rate', 'Pass rate', 'pct', '%'), col('result', 'Result', 'status')],
    keys.map((k, i) => { const x = cmp.sla[i]; const ev = (x.PASS ?? 0) + (x.WARNING ?? 0) + (x.FAIL ?? 0); return { runKey: `${L(i)} · ${k}`, PASS: x.PASS ?? 0, WARNING: x.WARNING ?? 0, FAIL: x.FAIL ?? 0, NO_DATA: x.NO_DATA ?? 0, rate: ev ? r2(((ev - (x.FAIL ?? 0)) / ev) * 100, 1) : null, result: ordered[i].result }; }),
    'Pass rate counts PASS and WARNING evaluations as compliant.'));
  sections.push(table('regressions', 'Recorded regressions', [col('runKey', 'Run', 'mono'), col('severity', 'Severity', 'status'), col('scope', 'Scope'), col('metric', 'Metric'), col('previous', 'Baseline', 'num'), col('current', 'Current', 'num'), col('change', 'Change', 'delta', '%')],
    regs.map((g) => ({ runKey: g.run_key, severity: g.severity, scope: g.transaction ?? g.scope, metric: metricName(g.metric), previous: r2(g.previous_value), current: r2(g.current_value), change: r2(g.change_pct, 1) })),
    regs.length ? undefined : 'No regressions are recorded for the compared runs.'));
  const infraKeys = ['cpu_avg', 'cpu_max', 'mem_max', 'heap_pct_max', 'gc_pause_max', 'db_latency_avg', 'db_active_max'];
  const im = cmp.metrics.filter((m) => infraKeys.includes(m.key));
  if (im.length) sections.push(chart('chart-infra', 'Infrastructure by run', { type: 'bar', unit: '%', xType: 'category', series: keys.map((k, i) => ({ name: `${L(i)} · ${k}`, data: im.filter((m) => m.unit === '%').map((m) => [m.label, r2(m.values[i], 1)] as [string, number | null]) })) }));

  sections.push(chapter('ch-appendix', 'Appendix', 'Glossary, methodology and report metadata.'));
  sections.push(kv('glossary', 'Glossary of metrics', GLOSSARY));
  sections.push({ id: 'methodology', title: 'Methodology', kind: 'list', data: methodology(anyApprox ? 'interval_weighted_approx' : summaries[0]?.percentile_method) });
  sections.push(kv('metadata', 'Report metadata', [['Report type', 'Comparison'], ['Report version', `v${version}`], ['Generated', new Date().toISOString()], ['Reference run', keys[0]], ['Runs', keys.join(', ')], ['Data sources', summaries.map((x, i) => `${L(i)}: ${x ? SOURCE_LABEL[x.source] ?? x.source : 'none'}`).join(' · ')]]));

  return {
    title, type: 'COMPARISON', generatedAt: new Date().toISOString(), version, audience: 'ENGINEERING', schema: 2, confidentiality: CONFIDENTIALITY,
    subject: { runKeys: keys, testName: [...new Set(ordered.map((r) => r.test_name))].join(', '), projectName: ordered[0]?.project_name, environment: [...new Set(ordered.map((r) => r.environment_name))].join(', ') },
    cover: { label: 'Comparison report', facts: [['Reference (A)', keys[0]], ...keys.slice(1).map((k, i) => [`Run ${L(i + 1)}`, k] as [string, string]), ['Test', [...new Set(ordered.map((r) => r.test_name))].join(', ')], ['Project', ordered[0]?.project_name ?? '—'], ['Environment', [...new Set(ordered.map((r) => r.environment_name))].join(', ')]] },
    sections,
  };
}

/* ------------------------------------------------------------------ shared: runs of a project in a period */

async function periodRuns(opts: { projectId: string; from: Date; to: Date; testId?: string | null; environmentId?: string | null }) {
  return query(
    `SELECT r.id, r.run_key, r.status, r.result, r.performance_score, r.build_number, r.test_id, COALESCE(r.started_at, r.created_at) AS started_at, t.name AS test_name, t.test_type, e.name AS environment_name,
            s.p95, s.p99, s.avg_rt, s.tps_avg, s.error_pct, s.sla_pass_pct, s.total_samples, s.percentile_method
     FROM test_runs r JOIN performance_tests t ON t.id = r.test_id JOIN environments e ON e.id = r.environment_id
     LEFT JOIN LATERAL (SELECT * FROM run_summary rs WHERE rs.run_id = r.id ORDER BY CASE rs.source WHEN 'live' THEN 0 WHEN 'jtl' THEN 1 WHEN 'import' THEN 2 ELSE 3 END LIMIT 1) s ON true
     WHERE r.project_id = $1 AND r.deleted_at IS NULL AND COALESCE(r.started_at, r.created_at) BETWEEN $2 AND $3
       AND ($4::uuid IS NULL OR r.test_id = $4) AND ($5::uuid IS NULL OR r.environment_id = $5)
     ORDER BY COALESCE(r.started_at, r.created_at) DESC`, [opts.projectId, opts.from, opts.to, opts.testId ?? null, opts.environmentId ?? null]);
}
const periodText = (from: Date, to: Date) => `${from.toISOString().slice(0, 10)} to ${to.toISOString().slice(0, 10)}`;
const scopeFacts = async (projectId: string, testId?: string | null, environmentId?: string | null) => {
  const [p, t, e] = await Promise.all([one(`SELECT name FROM projects WHERE id = $1`, [projectId]), testId ? one(`SELECT name FROM performance_tests WHERE id = $1`, [testId]) : null, environmentId ? one(`SELECT name FROM environments WHERE id = $1`, [environmentId]) : null]);
  return { project: p?.name as string | undefined, test: t?.name as string | undefined, environment: e?.name as string | undefined };
};

/* ------------------------------------------------------------------ Executive */

export async function buildExecutiveContent(opts: { orgId: string; projectId: string; from: Date; to: Date; testId?: string | null; environmentId?: string | null }, version: number, title: string): Promise<ReportContent> {
  const names = await scopeFacts(opts.projectId, opts.testId, opts.environmentId);
  const trend = await loadTrend({ orgId: opts.orgId, projectId: opts.projectId, testId: opts.testId, environmentId: opts.environmentId, groupBy: 'date', from: opts.from, to: opts.to, limit: 500 });
  const runs = await periodRuns(opts);
  const ids = runs.map((r) => r.id);
  const [regs, slaAgg, slow] = ids.length ? await Promise.all([
    query(`SELECT g.*, r.run_key, t.name AS test_name FROM regressions g JOIN test_runs r ON r.id = g.run_id JOIN performance_tests t ON t.id = r.test_id WHERE g.run_id = ANY($1::uuid[]) AND g.direction = 'REGRESSION'
           ORDER BY CASE g.severity WHEN 'CRITICAL' THEN 0 WHEN 'WARNING' THEN 1 ELSE 2 END, abs(g.change_pct) DESC NULLS LAST`, [ids]),
    one(`SELECT count(*) FILTER (WHERE status <> 'NO_DATA')::int evaluated, count(*) FILTER (WHERE status IN ('PASS','WARNING'))::int passed, count(*) FILTER (WHERE status = 'FAIL')::int failed FROM sla_results WHERE run_id = ANY($1::uuid[])`, [ids]),
    query(`SELECT DISTINCT ON (t.name, r.test_id) t.name, pt.name AS test_name, r.run_key, t.p95, t.tps, t.error_pct, t.samples
           FROM transactions t JOIN test_runs r ON r.id = t.run_id JOIN performance_tests pt ON pt.id = r.test_id
           WHERE t.run_id = ANY($1::uuid[]) AND t.p95 IS NOT NULL AND r.status = 'COMPLETED'
           ORDER BY t.name, r.test_id, COALESCE(r.started_at, r.created_at) DESC`, [ids]),
  ]) : [[], null, []];
  const completed = runs.filter((r) => r.status === 'COMPLETED');
  const withResult = completed.filter((r) => r.result);
  const passed = withResult.filter((r) => r.result === 'PASS' || r.result === 'PASS_WITH_WARNINGS').length;
  const slaPct = slaAgg?.evaluated ? (slaAgg.passed / slaAgg.evaluated) * 100 : null;
  const passRate = withResult.length ? (passed / withResult.length) * 100 : null;
  const critical = regs.filter((g: any) => g.severity === 'CRITICAL').length;
  const degr = trend.degradation.filter((d) => d.direction !== 'STABLE');
  const degrading = degr.filter((d) => d.direction === 'DEGRADING');
  const sections: Section[] = [];

  // Per test roll-up
  const byTest = new Map<string, any[]>();
  for (const r of runs) { const a = byTest.get(r.test_name) ?? []; a.push(r); byTest.set(r.test_name, a); }
  const testRows = [...byTest.entries()].map(([name, rs]) => {
    const wr = rs.filter((r) => r.result);
    const ok = wr.filter((r) => r.result === 'PASS' || r.result === 'PASS_WITH_WARNINGS').length;
    const latest = rs.find((r) => r.result) ?? rs[0];
    return { test: name, type: latest.test_type, runs: rs.length, pass: wr.filter((r) => r.result === 'PASS').length, warn: wr.filter((r) => r.result === 'PASS_WITH_WARNINGS').length, fail: wr.filter((r) => r.result === 'FAIL').length,
      rate: wr.length ? r2((ok / wr.length) * 100, 1) : null, p95: r2(avgOf(rs.map((r) => n(r.p95))), 0), tps: r2(avgOf(rs.map((r) => n(r.tps_avg))), 1), latest: latest.result ?? latest.status, trend: [...rs].reverse().map((r) => r2(r.p95, 0)) };
  }).sort((a, b) => (a.rate ?? 101) - (b.rate ?? 101));

  const findings: SummaryData['findings'] = [];
  const failingTests = testRows.filter((t) => t.latest === 'FAIL');
  if (failingTests.length) findings.push({ tone: 'fail', text: `${plural(failingTests.length, 'test')} failed on the latest run: ${failingTests.slice(0, 3).map((t) => t.test).join(', ')}.` });
  if (regs.length) findings.push({ tone: critical ? 'fail' : 'warn', text: `${plural(regs.length, 'regression')} recorded${critical ? ` (${critical} critical)` : ''}; largest: ${regs[0].test_name} — ${regs[0].transaction ?? regs[0].scope} ${metricName(regs[0].metric)} ${fmtSigned(r2(regs[0].change_pct, 0), 0)}%.` });
  for (const d of degrading.slice(0, 3 - findings.length)) findings.push({ tone: d.severity === 'CRITICAL' ? 'fail' : 'warn', text: d.message });
  if (findings.length < 3 && slaPct != null) findings.push({ tone: slaPct >= 95 ? 'pass' : slaPct >= 80 ? 'warn' : 'fail', text: `SLA compliance across ${fmtInt(slaAgg.evaluated)} rule evaluations was ${fmtNum(slaPct, 1)}%.` });
  if (findings.length < 3 && passRate != null) findings.push({ tone: passRate >= 90 ? 'pass' : 'warn', text: `${fmtNum(passRate, 0)}% of analysed runs passed (${passed}/${withResult.length}).` });
  const recs = ids.length ? await query(`SELECT title, min(description) AS description, min(CASE priority WHEN 'HIGH' THEN 0 WHEN 'MEDIUM' THEN 1 ELSE 2 END) AS pr, count(*)::int AS n FROM recommendations WHERE run_id = ANY($1::uuid[]) GROUP BY title ORDER BY 3, 4 DESC LIMIT 3`, [ids]) : [];
  const overall = passRate == null ? 'INCONCLUSIVE' : critical || passRate < 70 ? 'FAIL' : passRate < 90 || regs.length ? 'PASS_WITH_WARNINGS' : 'PASS';
  sections.push(chapter('ch-summary', 'Executive summary', `Performance testing of ${names.project ?? 'the project'} from ${periodText(opts.from, opts.to)}${names.test ? ` — test “${names.test}”` : ''}${names.environment ? ` — ${names.environment}` : ''}.`));
  sections.push({ id: 'summary', title: 'Overview', kind: 'summary', data: {
    paragraphs: runs.length ? [
      `${names.project ?? 'This project'} executed ${plural(runs.length, 'test run')} across ${plural(byTest.size, 'test')} between ${periodText(opts.from, opts.to)}; ${completed.length} completed.`
        + (passRate != null ? ` ${fmtNum(passRate, 0)}% of analysed runs passed (${passed}/${withResult.length}).` : ''),
      (slaPct != null ? `SLA compliance across all evaluated rules was ${fmtNum(slaPct, 1)}%. ` : 'No SLA rules were evaluated. ') + (regs.length ? `${plural(regs.length, 'regression finding')} ${regs.length === 1 ? 'was' : 'were'} recorded${critical ? `, ${critical} of them critical` : ''}.` : 'No regressions were recorded.')
        + (degrading.length ? ` ${plural(degrading.length, 'metric')} show a sustained degrading trend.` : ''),
    ] : ['No test runs were executed in this period.'],
    findings: findings.slice(0, 3),
    recommendations: recs.map((x) => ({ text: `${x.title}: ${x.description}${x.n > 1 ? ` (raised in ${x.n} runs)` : ''}`, priority: ['HIGH', 'MEDIUM', 'LOW'][x.pr] })),
    risk: overall === 'FAIL' ? { level: 'HIGH', reason: critical ? `${critical} critical regression(s) in the period.` : `Only ${fmtNum(passRate, 0)}% of runs passed.` }
      : overall === 'PASS_WITH_WARNINGS' ? { level: 'MEDIUM', reason: regs.length ? 'Regressions were recorded in the period.' : 'Pass rate below 90%.' }
      : overall === 'PASS' ? { level: 'LOW', reason: 'High pass rate and no regressions.' } : { level: 'MEDIUM', reason: 'Not enough analysed runs to assess risk.' },
  } satisfies SummaryData });
  sections.push({ id: 'kpis', title: 'Key figures', kind: 'kpis', data: [
    { label: 'Runs', value: runs.length, hint: `${completed.length} completed` }, { label: 'Tests', value: byTest.size },
    { label: 'Pass rate', value: r2(passRate, 1), unit: '%', status: passRate == null ? null : passRate >= 90 ? 'PASS' : passRate >= 70 ? 'WARNING' : 'FAIL', better: 'higher' },
    { label: 'SLA compliance', value: r2(slaPct, 1), unit: '%', status: slaPct == null ? null : slaPct >= 95 ? 'PASS' : slaPct >= 80 ? 'WARNING' : 'FAIL', better: 'higher' },
    { label: 'Avg P95', value: r2(avgOf(completed.map((r) => n(r.p95))), 0), unit: 'ms', better: 'lower', approx: completed.some((r) => r.percentile_method === 'interval_weighted_approx') || undefined },
    { label: 'Avg throughput', value: r2(avgOf(completed.map((r) => n(r.tps_avg))), 1), unit: 'TPS', better: 'higher' },
    { label: 'Avg error rate', value: r2(avgOf(completed.map((r) => n(r.error_pct))), 2), unit: '%', better: 'lower' },
    { label: 'Avg score', value: r2(avgOf(completed.map((r) => n(r.performance_score))), 0), unit: '/100', better: 'higher' },
    { label: 'Regressions', value: regs.length, status: regs.length ? (critical ? 'FAIL' : 'WARNING') : 'PASS', better: 'lower', hint: critical ? `${critical} critical` : undefined },
    { label: 'Degrading trends', value: degrading.length, status: degrading.length ? 'WARNING' : 'PASS' },
  ] satisfies Kpi[] });

  sections.push(chapter('ch-tests', 'Test outcomes', 'Pass rate and headline figures per test, and the distribution of results.'));
  sections.push(table('tests', 'Pass rate by test', [col('test', 'Test'), col('type', 'Type'), col('runs', 'Runs', 'int'), col('pass', 'Pass', 'int'), col('warn', 'Warn', 'int'), col('fail', 'Fail', 'int'), col('rate', 'Pass rate', 'pct', '%'), col('p95', 'Avg P95', 'int', 'ms'), col('tps', 'Avg TPS', 'num1'), col('latest', 'Latest', 'status'), col('trend', 'P95 trend', 'spark')], testRows,
    'Pass rate counts PASS and PASS WITH WARNINGS as passed. Sorted from lowest pass rate.'));
  const dist: Record<string, number> = {};
  for (const r of runs) { const k = r.result ?? r.status; dist[k] = (dist[k] ?? 0) + 1; }
  sections.push(table('results', 'Result distribution', [col('result', 'Result', 'status'), col('count', 'Runs', 'int'), col('share', 'Share', 'pct', '%')], Object.entries(dist).sort((a, b) => b[1] - a[1]).map(([k, v]) => ({ result: k, count: v, share: r2((v / runs.length) * 100, 1) }))));

  sections.push(chapter('ch-trends', 'Trends', 'How the key metrics moved across completed runs in the period, and the sustained trend signals detected.'));
  const pts = trend.points;
  if (pts.length > 1) {
    const multi = new Set(pts.map((p) => p.testId)).size > 1;
    const byT = (k: TrendMetric, d = 0) => {
      if (!multi) return [{ name: TREND_METRICS[k].label, data: pts.map((p) => [new Date(p.startedAt).getTime(), r2(p.metrics[k], d)] as [number, number | null]) }];
      const groups = new Map<string, typeof pts>();
      for (const p of pts) { const a = groups.get(p.testName) ?? []; a.push(p); groups.set(p.testName, a); }
      return [...groups.entries()].slice(0, 6).map(([name, ps], i) => ({ name, style: (['solid', 'dashed', 'dotted'] as const)[i % 3], data: ps.map((p) => [new Date(p.startedAt).getTime(), r2(p.metrics[k], d)] as [number, number | null]) }));
    };
    sections.push(chart('chart-p95', 'P95 trend', { type: 'line', unit: 'ms', yLabel: 'P95 (ms)', xType: 'time', series: byT('p95') }));
    sections.push(chart('chart-tps', 'Throughput trend', { type: 'line', unit: 'TPS', yLabel: 'TPS', xType: 'time', series: byT('tps', 1) }));
    sections.push(chart('chart-err', 'Error-rate trend', { type: 'line', unit: '%', yLabel: 'Errors (%)', xType: 'time', series: byT('errorPct', 2) }));
    sections.push(chart('chart-score', 'Performance-score trend', { type: 'line', unit: 'pts', yLabel: 'Score', xType: 'time', series: byT('score', 0) }));
  } else sections.push({ id: 'no-trend', title: 'Trend charts', kind: 'text', data: 'At least two completed runs are needed to draw trends.' });
  sections.push({ id: 'trends', title: 'Trend signals', kind: 'findings', data: degr.slice(0, 15).map((d) => ({ severity: d.direction === 'IMPROVING' ? 'IMPROVEMENT' : d.severity, title: `${d.direction === 'IMPROVING' ? 'Improving' : 'Degrading'}: ${TREND_METRICS[d.metric as TrendMetric]?.label ?? d.metric}${d.testName ? ` — ${d.testName}` : ''}`, description: d.message })) satisfies Finding[], note: degr.length ? undefined : 'No sustained degradation or improvement detected in this window.' });

  sections.push(chapter('ch-risks', 'Risks & regressions', 'Top risks for the period, recorded regressions and the slowest transactions.'));
  const risks: Finding[] = [];
  for (const t of failingTests.slice(0, 4)) risks.push({ severity: 'FAIL', title: `${t.test} is failing`, description: `Latest run failed; pass rate ${fmtNum(t.rate, 0)}% over ${plural(t.runs, 'run')}.` });
  for (const g of regs.filter((x: any) => x.severity === 'CRITICAL').slice(0, 4)) risks.push({ severity: 'CRITICAL', title: `${g.test_name}: ${g.transaction ?? g.scope} ${metricName(g.metric)} regression`, description: `${fmtNum(n(g.previous_value), 2)} → ${fmtNum(n(g.current_value), 2)} (${fmtSigned(r2(g.change_pct, 1), 1)}%) in ${g.run_key}.` });
  for (const d of degrading.filter((x) => x.severity === 'CRITICAL').slice(0, 3)) risks.push({ severity: 'CRITICAL', title: `Degrading ${TREND_METRICS[d.metric as TrendMetric]?.label ?? d.metric}`, description: d.message });
  if (slaPct != null && slaPct < 95) risks.push({ severity: slaPct < 80 ? 'FAIL' : 'WARNING', title: 'SLA compliance below 95%', description: `${fmtInt(slaAgg.failed)} of ${fmtInt(slaAgg.evaluated)} rule evaluations failed.` });
  sections.push({ id: 'risks', title: 'Top risks', kind: 'findings', data: risks.slice(0, 8), note: risks.length ? undefined : 'No failing tests, critical regressions or critical trends in this period.' });
  sections.push(table('regressions', 'Top regressions', [col('runKey', 'Run', 'mono'), col('test', 'Test'), col('severity', 'Severity', 'status'), col('scope', 'Scope'), col('metric', 'Metric'), col('previous', 'Baseline', 'num'), col('current', 'Current', 'num'), col('change', 'Change', 'delta', '%')],
    regs.slice(0, 20).map((g: any) => ({ runKey: g.run_key, test: g.test_name, severity: g.severity, scope: g.transaction ?? g.scope, metric: metricName(g.metric), previous: r2(g.previous_value), current: r2(g.current_value), change: r2(g.change_pct, 1) })),
    regs.length > 20 ? `Showing 20 of ${regs.length}.` : regs.length ? undefined : 'No regressions recorded in this period.'));
  const slowest = [...(slow as any[])].sort((a, b) => b.p95 - a.p95).slice(0, 10);
  if (slowest.length) {
    sections.push(chart('chart-slowest', 'Slowest transactions (latest run of each test, P95)', { type: 'bar', unit: 'ms', xType: 'category', series: [{ name: 'P95', data: slowest.map((t) => [`${t.name}`, r2(t.p95, 0)]) }] }));
    sections.push(table('slowest', 'Slowest transactions', [col('name', 'Transaction'), col('test', 'Test'), col('runKey', 'Run', 'mono'), col('samples', 'Samples', 'int'), col('p95', 'P95', 'int', 'ms'), col('tps', 'TPS', 'num'), col('errorPct', 'Errors', 'pct', '%')],
      slowest.map((t) => ({ name: t.name, test: t.test_name, runKey: t.run_key, samples: n(t.samples), p95: r2(t.p95, 0), tps: r2(t.tps), errorPct: r2(t.error_pct) }))));
  }
  sections.push(chapter('ch-appendix', 'Appendix', 'All runs in the period, glossary, methodology and report metadata.'));
  sections.push(table('runs', 'Runs in period', [col('runKey', 'Run ID', 'mono'), col('test', 'Test'), col('environment', 'Env'), col('build', 'Build'), col('started', 'Started', 'date'), col('result', 'Result', 'status'), col('score', 'Score', 'int'), col('p95', 'P95', 'int', 'ms'), col('tps', 'TPS', 'num1'), col('errorPct', 'Err', 'pct', '%')],
    runs.slice(0, 100).map((r) => ({ runKey: r.run_key, test: r.test_name, environment: r.environment_name, build: r.build_number ?? '—', started: iso(r.started_at), result: r.result ?? r.status, score: r.performance_score != null ? Math.round(r.performance_score) : null, p95: r2(r.p95, 0), tps: r2(r.tps_avg, 1), errorPct: r2(r.error_pct) })),
    runs.length > 100 ? `Showing the latest 100 of ${runs.length} runs.` : undefined));
  sections.push(kv('glossary', 'Glossary of metrics', GLOSSARY));
  sections.push({ id: 'methodology', title: 'Methodology', kind: 'list', data: [...methodology(null).slice(0, 1), 'Pass rate = runs with result PASS or PASS WITH WARNINGS divided by completed runs with a result. Averages are simple means over completed runs. Trend signals use an ordinary least-squares slope over consecutive runs of the same test and environment plus the count of consecutive worsening runs.'] });
  sections.push(kv('metadata', 'Report metadata', [['Report type', 'Executive summary'], ['Report version', `v${version}`], ['Generated', new Date().toISOString()], ['Project', names.project ?? '—'], ['Period', periodText(opts.from, opts.to)], ['Test filter', names.test ?? 'All tests'], ['Environment filter', names.environment ?? 'All environments']]));

  return {
    title, type: 'EXECUTIVE', generatedAt: new Date().toISOString(), version, audience: 'EXECUTIVE', schema: 2, confidentiality: CONFIDENTIALITY,
    subject: { projectName: names.project, testName: names.test, environment: names.environment, from: opts.from.toISOString(), to: opts.to.toISOString() },
    result: { status: overall, score: r2(avgOf(completed.map((r) => n(r.performance_score))), 0), breakdown: { 'Pass rate': passRate == null ? 'N/A' : passRate >= 90 ? 'PASS' : passRate >= 70 ? 'WARNING' : 'FAIL', SLA: slaPct == null ? 'N/A' : slaPct >= 95 ? 'PASS' : slaPct >= 80 ? 'WARNING' : 'FAIL', Regressions: critical ? 'FAIL' : regs.length ? 'WARNING' : 'PASS' } },
    cover: { label: 'Executive summary', facts: [['Project', names.project ?? '—'], ['Period', periodText(opts.from, opts.to)], ['Tests', names.test ?? `All (${byTest.size})`], ['Environment', names.environment ?? 'All'], ['Runs', `${runs.length} (${completed.length} completed)`]] },
    sections,
  };
}

/* ------------------------------------------------------------------ SLA compliance */

export async function buildSlaContent(opts: { orgId: string; projectId: string; from: Date; to: Date; testId?: string | null; environmentId?: string | null }, version: number, title: string): Promise<ReportContent> {
  const names = await scopeFacts(opts.projectId, opts.testId, opts.environmentId);
  const runs = (await periodRuns(opts)).filter((r) => r.status === 'COMPLETED');
  const ids = runs.map((r) => r.id);
  const res = ids.length ? await query(
    `SELECT s.run_id, s.rule_id, s.scope, s.transaction, s.metric, s.direction, s.actual_value, s.warning_value, s.critical_value, s.unit, s.status, rl.name AS rule_name, rl.transaction_pattern, sp.name AS profile_name
     FROM sla_results s LEFT JOIN sla_rules rl ON rl.id = s.rule_id LEFT JOIN sla_profiles sp ON sp.id = s.profile_id WHERE s.run_id = ANY($1::uuid[])`, [ids]) : [];
  const runById = new Map(runs.map((r) => [r.id, r]));
  const ev = res.filter((x) => x.status !== 'NO_DATA');
  const cnt = (xs: any[], st: string) => xs.filter((x) => x.status === st).length;
  const comp = (xs: any[]) => { const e = xs.filter((x) => x.status !== 'NO_DATA'); return e.length ? (e.filter((x) => x.status !== 'FAIL').length / e.length) * 100 : null; };
  const strict = (xs: any[]) => { const e = xs.filter((x) => x.status !== 'NO_DATA'); return e.length ? (e.filter((x) => x.status === 'PASS').length / e.length) * 100 : null; };
  const overallPct = comp(res);
  const evaluatedRuns = runs.filter((r) => res.some((x) => x.run_id === r.id && x.status !== 'NO_DATA'));
  const fullyCompliant = evaluatedRuns.filter((r) => !res.some((x) => x.run_id === r.id && x.status === 'FAIL')).length;
  const tone = (p: number | null) => (p == null ? null : p >= 95 ? 'PASS' : p >= 80 ? 'WARNING' : 'FAIL');
  const group = <K>(xs: any[], key: (x: any) => K) => { const m = new Map<K, any[]>(); for (const x of xs) { const k = key(x); const a = m.get(k) ?? []; a.push(x); m.set(k, a); } return m; };
  const sections: Section[] = [];

  const byRule = [...group(res, (x) => `${x.rule_id ?? x.metric}|${x.scope}`).values()].map((xs) => {
    const x = xs[0];
    const e = xs.filter((y) => y.status !== 'NO_DATA');
    const worst = e.reduce((w: any, y: any) => (w == null || (x.direction === 'HIGHER' ? y.actual_value < w.actual_value : y.actual_value > w.actual_value) ? y : w), null);
    return { rule: slaRuleName(x), scope: x.scope === 'RUN' ? 'Whole run' : `Transactions${x.transaction_pattern ? ` (${x.transaction_pattern})` : ''}`, evals: e.length, pass: cnt(xs, 'PASS'), warn: cnt(xs, 'WARNING'), fail: cnt(xs, 'FAIL'), pct: r2(comp(xs), 1), worst: r2(worst?.actual_value), limit: r2(x.critical_value ?? x.warning_value), unit: x.unit ?? '', status: tone(comp(xs)) };
  }).sort((a, b) => (a.pct ?? 101) - (b.pct ?? 101) || b.fail - a.fail);
  const byTest = [...group(res, (x) => runById.get(x.run_id)?.test_name ?? '—').entries()].map(([test, xs]) => ({ test, runs: new Set(xs.map((x) => x.run_id)).size, evals: xs.filter((x) => x.status !== 'NO_DATA').length, pass: cnt(xs, 'PASS'), warn: cnt(xs, 'WARNING'), fail: cnt(xs, 'FAIL'), pct: r2(comp(xs), 1), status: tone(comp(xs)) })).sort((a, b) => (a.pct ?? 101) - (b.pct ?? 101));
  const txViol = [...group(res.filter((x) => x.transaction && x.status !== 'NO_DATA'), (x) => x.transaction as string).entries()].map(([name, xs]) => ({ name, evals: xs.length, warn: cnt(xs, 'WARNING'), fail: cnt(xs, 'FAIL'), pct: r2(comp(xs), 1), metrics: [...new Set(xs.filter((x) => x.status === 'FAIL').map((x) => SLA_METRIC_LABEL[x.metric] ?? x.metric))].join(', ') || '—' }))
    .filter((t) => t.fail + t.warn > 0).sort((a, b) => b.fail - a.fail || b.warn - a.warn).slice(0, 20);

  const worstRule = byRule.find((r) => r.fail > 0);
  sections.push(chapter('ch-summary', 'Executive summary', `SLA compliance of ${names.project ?? 'the project'} from ${periodText(opts.from, opts.to)}${names.test ? ` — test “${names.test}”` : ''}${names.environment ? ` — ${names.environment}` : ''}.`));
  const findings: SummaryData['findings'] = [];
  if (worstRule) findings.push({ tone: 'fail', text: `Most violated rule: ${worstRule.rule} (${worstRule.scope.toLowerCase()}) failed ${plural(worstRule.fail, 'time')} — compliance ${fmtNum(worstRule.pct, 1)}%.` });
  if (byTest.length && byTest[0].fail) findings.push({ tone: tone(byTest[0].pct) === 'FAIL' ? 'fail' : 'warn', text: `Least compliant test: ${byTest[0].test} at ${fmtNum(byTest[0].pct, 1)}% (${byTest[0].fail} failed evaluations).` });
  if (txViol.length) findings.push({ tone: 'warn', text: `Transaction with most violations: ${txViol[0].name} (${txViol[0].fail} failed, ${txViol[0].warn} warnings${txViol[0].metrics !== '—' ? `; ${txViol[0].metrics}` : ''}).` });
  if (findings.length < 3 && evaluatedRuns.length) findings.push({ tone: fullyCompliant === evaluatedRuns.length ? 'pass' : 'warn', text: `${fullyCompliant} of ${plural(evaluatedRuns.length, 'evaluated run')} met every SLA rule.` });
  const recs: SummaryData['recommendations'] = [];
  if (worstRule) recs.push({ priority: 'HIGH', text: `Investigate ${worstRule.rule}: the worst measured value was ${fmtNum(worstRule.worst, 2)} ${worstRule.unit} against a limit of ${fmtNum(worstRule.limit, 2)} ${worstRule.unit}.` });
  if (txViol.length) recs.push({ priority: 'MEDIUM', text: `Profile the ${Math.min(3, txViol.length)} transaction(s) with the most violations: ${txViol.slice(0, 3).map((t) => t.name).join(', ')}.` });
  if (runs.length && !res.length) recs.push({ priority: 'MEDIUM', text: 'Attach an SLA profile to the tests so every run is evaluated automatically.' });
  sections.push({ id: 'summary', title: 'Overview', kind: 'summary', data: {
    paragraphs: res.length ? [
      `${plural(runs.length, 'completed run')} of ${plural(new Set(runs.map((r) => r.test_id)).size, 'test')} ${runs.length === 1 ? 'was' : 'were'} executed in the period; ${evaluatedRuns.length} had SLA rules evaluated, producing ${fmtInt(ev.length)} rule evaluations.`,
      `Overall compliance was ${fmtNum(overallPct, 1)}% (${cnt(res, 'PASS')} passed, ${cnt(res, 'WARNING')} warnings, ${cnt(res, 'FAIL')} failed). ${fullyCompliant} of ${evaluatedRuns.length} runs met every rule.`,
    ] : [runs.length ? `${plural(runs.length, 'completed run')} ${runs.length === 1 ? 'was' : 'were'} executed in the period, but none had SLA rules evaluated.` : 'No completed runs in this period.'],
    findings: findings.slice(0, 3), recommendations: recs.slice(0, 3),
    risk: overallPct == null ? { level: 'MEDIUM', reason: 'No SLA evaluations — compliance cannot be assessed.' } : overallPct < 80 ? { level: 'HIGH', reason: `Compliance ${fmtNum(overallPct, 1)}% is below 80%.` } : overallPct < 95 ? { level: 'MEDIUM', reason: `Compliance ${fmtNum(overallPct, 1)}% is below the 95% target.` } : { level: 'LOW', reason: `Compliance ${fmtNum(overallPct, 1)}% meets the 95% target.` },
  } satisfies SummaryData });
  sections.push({ id: 'kpis', title: 'Key figures', kind: 'kpis', data: [
    { label: 'Compliance', value: r2(overallPct, 1), unit: '%', status: tone(overallPct), hint: 'PASS + WARNING' }, { label: 'Strict pass', value: r2(strict(res), 1), unit: '%', hint: 'PASS only' },
    { label: 'Runs evaluated', value: evaluatedRuns.length, hint: `of ${runs.length} completed` }, { label: 'Fully compliant runs', value: fullyCompliant, status: evaluatedRuns.length ? (fullyCompliant === evaluatedRuns.length ? 'PASS' : 'WARNING') : null },
    { label: 'Evaluations', value: ev.length }, { label: 'Failed', value: cnt(res, 'FAIL'), status: cnt(res, 'FAIL') ? 'FAIL' : 'PASS' }, { label: 'Warnings', value: cnt(res, 'WARNING'), status: cnt(res, 'WARNING') ? 'WARNING' : null }, { label: 'No data', value: cnt(res, 'NO_DATA') },
  ] satisfies Kpi[] });

  sections.push(chapter('ch-over-time', 'Compliance over time', 'Compliance of each evaluated run in chronological order.'));
  const perRun = [...evaluatedRuns].reverse().map((r) => { const xs = res.filter((x) => x.run_id === r.id); return { r, xs, pct: comp(xs), strictPct: strict(xs) }; });
  if (perRun.length > 1) sections.push(chart('chart-compliance', 'Compliance per run', { type: 'line', unit: '%', yLabel: 'Compliance (%)', xType: 'time', series: [{ name: 'Compliance (PASS + WARNING)', data: perRun.map((p) => [new Date(p.r.started_at).getTime(), r2(p.pct, 1)]) }, { name: 'Strict (PASS only)', style: 'dashed', data: perRun.map((p) => [new Date(p.r.started_at).getTime(), r2(p.strictPct, 1)]) }], thresholds: [{ label: 'Target 95%', value: 95, status: 'WARNING' }] }));
  sections.push(table('runs', 'Compliance by run', [col('runKey', 'Run ID', 'mono'), col('test', 'Test'), col('started', 'Started', 'date'), col('evals', 'Rules', 'int'), col('pass', 'Pass', 'int'), col('warn', 'Warn', 'int'), col('fail', 'Fail', 'int'), col('pct', 'Compliance', 'pct', '%'), col('result', 'Run result', 'status')],
    [...perRun].reverse().slice(0, 100).map((p) => ({ runKey: p.r.run_key, test: p.r.test_name, started: iso(p.r.started_at), evals: p.xs.filter((x) => x.status !== 'NO_DATA').length, pass: cnt(p.xs, 'PASS'), warn: cnt(p.xs, 'WARNING'), fail: cnt(p.xs, 'FAIL'), pct: r2(p.pct, 1), result: p.r.result })),
    perRun.length ? undefined : 'No runs with SLA evaluations in this period.'));

  sections.push(chapter('ch-breakdown', 'Compliance breakdown', 'Compliance by test, by rule and by transaction.'));
  sections.push(table('by-test', 'By test', [col('test', 'Test'), col('runs', 'Runs', 'int'), col('evals', 'Evaluations', 'int'), col('pass', 'Pass', 'int'), col('warn', 'Warn', 'int'), col('fail', 'Fail', 'int'), col('pct', 'Compliance', 'pct', '%'), col('status', 'Status', 'status')], byTest));
  if (byRule.length) sections.push(chart('chart-rules', 'Compliance by rule', { type: 'bar', unit: '%', xType: 'category', series: [{ name: 'Compliance', data: byRule.slice(0, 15).map((r) => [`${r.rule} · ${r.scope}`, r.pct]) }] }));
  sections.push(table('by-rule', 'By rule', [col('rule', 'Rule'), col('scope', 'Scope'), col('evals', 'Evals', 'int'), col('pass', 'Pass', 'int'), col('warn', 'Warn', 'int'), col('fail', 'Fail', 'int'), col('pct', 'Compliance', 'pct', '%'), col('worst', 'Worst actual', 'num'), col('limit', 'Limit', 'num'), col('unit', 'Unit'), col('status', 'Status', 'status')], byRule,
    'Worst actual is the least favourable measured value across all evaluations of the rule; limit is the critical (else warning) threshold.'));
  sections.push(table('by-txn', 'Most violated transactions', [col('name', 'Transaction'), col('evals', 'Evaluations', 'int'), col('warn', 'Warn', 'int'), col('fail', 'Fail', 'int'), col('pct', 'Compliance', 'pct', '%'), col('metrics', 'Failing metrics')], txViol,
    txViol.length ? undefined : 'No transaction-level violations.'));

  sections.push(chapter('ch-violations', 'Violations', 'Every failed or warning evaluation (latest first).'));
  const viol = res.filter((x) => x.status === 'FAIL' || x.status === 'WARNING').sort((a, b) => new Date(runById.get(b.run_id)!.started_at).getTime() - new Date(runById.get(a.run_id)!.started_at).getTime() || sevRank(a.status) - sevRank(b.status));
  sections.push(table('violations', 'Violation detail', [col('runKey', 'Run', 'mono'), col('rule', 'Rule'), col('scope', 'Scope'), col('actual', 'Actual', 'num'), col('limit', 'Limit', 'num'), col('unit', 'Unit'), col('margin', 'Margin', 'delta', '%'), col('status', 'Status', 'status')],
    viol.slice(0, 80).map((x) => ({ runKey: runById.get(x.run_id)?.run_key, rule: slaRuleName(x), scope: x.transaction ?? 'Whole run', actual: r2(x.actual_value), limit: r2(x.critical_value ?? x.warning_value), unit: x.unit ?? '', margin: r2(slaMargin(n(x.actual_value), n(x.warning_value), n(x.critical_value), x.direction), 1), status: x.status })),
    viol.length > 80 ? `Showing the latest 80 of ${viol.length} violations.` : viol.length ? undefined : 'No violations in this period.'));

  sections.push(chapter('ch-appendix', 'Appendix', 'Glossary, methodology and report metadata.'));
  sections.push(kv('glossary', 'Glossary of metrics', GLOSSARY));
  sections.push({ id: 'methodology', title: 'Methodology', kind: 'list', data: [methodology(null)[3], 'Compliance = evaluations with status PASS or WARNING divided by all evaluations with data. Strict pass counts PASS only. NO DATA evaluations (metric not collected) are excluded. Only completed runs in the period are included.'] });
  sections.push(kv('metadata', 'Report metadata', [['Report type', 'SLA compliance'], ['Report version', `v${version}`], ['Generated', new Date().toISOString()], ['Project', names.project ?? '—'], ['Period', periodText(opts.from, opts.to)], ['Test filter', names.test ?? 'All tests'], ['Environment filter', names.environment ?? 'All environments'], ['SLA profiles', [...new Set(res.map((x) => x.profile_name).filter(Boolean))].join(', ') || '—']]));

  const status = overallPct == null ? 'INCONCLUSIVE' : overallPct >= 95 ? 'PASS' : overallPct >= 80 ? 'PASS_WITH_WARNINGS' : 'FAIL';
  return {
    title, type: 'SLA', generatedAt: new Date().toISOString(), version, audience: 'EXECUTIVE', schema: 2, confidentiality: CONFIDENTIALITY,
    subject: { projectName: names.project, testName: names.test, environment: names.environment, from: opts.from.toISOString(), to: opts.to.toISOString() },
    result: { status, score: overallPct == null ? null : Math.round(overallPct), breakdown: { Compliance: tone(overallPct) ?? 'N/A', 'Failed rules': cnt(res, 'FAIL') ? 'FAIL' : res.length ? 'PASS' : 'N/A', Warnings: cnt(res, 'WARNING') ? 'WARNING' : res.length ? 'PASS' : 'N/A' } },
    cover: { label: 'SLA compliance report', facts: [['Project', names.project ?? '—'], ['Period', periodText(opts.from, opts.to)], ['Tests', names.test ?? 'All'], ['Environment', names.environment ?? 'All'], ['Runs evaluated', `${evaluatedRuns.length} of ${runs.length}`], ['Compliance', overallPct == null ? 'n/a' : `${fmtNum(overallPct, 1)}%`]] },
    sections,
  };
}

/* ------------------------------------------------------------------ Trend (one test) */

function trendChange(k: TrendMetric, pts: { metrics: Record<string, number | null> }[]) {
  const vals = pts.map((p) => p.metrics[k]).filter((v): v is number => v != null);
  if (vals.length < 2) return '—';
  const def = TREND_METRICS[k];
  if (def?.absolute) return `${fmtSigned(vals[vals.length - 1] - vals[0], 2)}${def.unit === '%' ? ' pts' : ''}`;
  const c = delta(vals[vals.length - 1], vals[0]);
  return c == null ? '—' : `${fmtSigned(c, 1)}%`;
}

export async function buildTrendContent(opts: { orgId: string; projectId: string; testId: string; from: Date; to: Date; environmentId?: string | null }, version: number, title: string): Promise<ReportContent> {
  const names = await scopeFacts(opts.projectId, opts.testId, opts.environmentId);
  const trend = await loadTrend({ orgId: opts.orgId, projectId: opts.projectId, testId: opts.testId, environmentId: opts.environmentId, groupBy: 'date', from: opts.from, to: opts.to, limit: 200 });
  const pts = trend.points;
  const ids = pts.map((p) => p.runId);
  const extra = ids.length ? await query(`SELECT r.id, r.result, r.virtual_users, s.users_peak, s.total_samples, s.percentile_method FROM test_runs r
    LEFT JOIN LATERAL (SELECT * FROM run_summary rs WHERE rs.run_id = r.id ORDER BY CASE rs.source WHEN 'live' THEN 0 WHEN 'jtl' THEN 1 WHEN 'import' THEN 2 ELSE 3 END LIMIT 1) s ON true WHERE r.id = ANY($1::uuid[])`, [ids]) : [];
  const ex = new Map(extra.map((x) => [x.id, x]));
  const approx = extra.some((x) => x.percentile_method === 'interval_weighted_approx');
  const sig = trend.degradation;
  const degr = sig.filter((d) => d.direction === 'DEGRADING');
  const impr = sig.filter((d) => d.direction === 'IMPROVING');
  const first = pts[0], last = pts[pts.length - 1];
  const sections: Section[] = [];
  const t = (p: { startedAt: string }) => new Date(p.startedAt).getTime();

  sections.push(chapter('ch-summary', 'Executive summary', `KPI trends for “${names.test ?? 'test'}”${names.environment ? ` in ${names.environment}` : ''} from ${periodText(opts.from, opts.to)}.`));
  const findings: SummaryData['findings'] = [];
  for (const d of degr.slice(0, 2)) findings.push({ tone: d.severity === 'CRITICAL' ? 'fail' : 'warn', text: d.message });
  for (const d of impr.slice(0, 3 - findings.length)) findings.push({ tone: 'pass', text: d.message });
  if (findings.length < 3 && pts.length >= 3 && !degr.length) findings.push({ tone: 'pass', text: `No sustained degradation across ${pts.length} runs.` });
  const regs = ids.length ? await query(`SELECT g.*, r.run_key FROM regressions g JOIN test_runs r ON r.id = g.run_id WHERE g.run_id = ANY($1::uuid[]) AND g.direction = 'REGRESSION'
                                        ORDER BY COALESCE(r.started_at, r.created_at) DESC, CASE g.severity WHEN 'CRITICAL' THEN 0 WHEN 'WARNING' THEN 1 ELSE 2 END LIMIT 30`, [ids]) : [];
  const recs = ids.length ? await query(`SELECT title, min(description) AS description, min(CASE priority WHEN 'HIGH' THEN 0 WHEN 'MEDIUM' THEN 1 ELSE 2 END) pr, count(*)::int n FROM recommendations WHERE run_id = ANY($1::uuid[]) GROUP BY title ORDER BY 3, 4 DESC LIMIT 3`, [ids]) : [];
  sections.push({ id: 'summary', title: 'Overview', kind: 'summary', data: {
    paragraphs: pts.length ? [
      `${plural(pts.length, 'completed run')} of “${names.test}” ${pts.length === 1 ? 'was' : 'were'} recorded between ${day(first.startedAt)} and ${day(last.startedAt)}.`
        + (pts.length > 1 ? ` P95 moved from ${approx ? '≈' : ''}${fmtMs(first.metrics.p95)} (${first.runKey}) to ${approx ? '≈' : ''}${fmtMs(last.metrics.p95)} (${last.runKey}); throughput from ${fmtNum(first.metrics.tps, 1)} to ${fmtNum(last.metrics.tps, 1)} TPS.` : ''),
      sig.length ? `${plural(degr.length, 'metric')} ${degr.length === 1 ? 'is' : 'are'} degrading and ${plural(impr.length, 'metric')} ${impr.length === 1 ? 'is' : 'are'} improving; the rest are stable.` : 'At least three runs are needed to classify trends.',
    ] : ['No completed runs of this test in the selected period.'],
    findings: findings.slice(0, 3),
    recommendations: recs.map((x) => ({ text: `${x.title}: ${x.description}${x.n > 1 ? ` (raised in ${x.n} runs)` : ''}`, priority: ['HIGH', 'MEDIUM', 'LOW'][x.pr] })),
    risk: degr.some((d) => d.severity === 'CRITICAL') ? { level: 'HIGH', reason: 'At least one metric shows a critical degrading trend.' } : degr.length ? { level: 'MEDIUM', reason: 'Some metrics are degrading.' } : pts.length >= 3 ? { level: 'LOW', reason: 'No metric shows a sustained degrading trend.' } : { level: 'MEDIUM', reason: 'Too few runs to assess the trend.' },
  } satisfies SummaryData });
  const tk = (label: string, k: TrendMetric, unit: string, d: number): Kpi => ({ label, value: r2(last?.metrics[k], d), unit, baseline: pts.length > 1 ? r2(first.metrics[k], d) : undefined, deltaPct: pts.length > 1 ? r2(delta(last.metrics[k], first.metrics[k]), 1) : null, better: TREND_METRICS[k].better, approx: (k === 'p95' || k === 'p99') && approx ? true : undefined, status: degr.find((x) => x.metric === k) ? (degr.find((x) => x.metric === k)!.severity === 'CRITICAL' ? 'FAIL' : 'WARNING') : impr.find((x) => x.metric === k) ? 'PASS' : null });
  if (pts.length) sections.push({ id: 'kpis', title: pts.length > 1 ? `Latest run vs first run (${first.runKey})` : 'Latest run', kind: 'kpis', data: [
    { label: 'Runs', value: pts.length }, tk('P95', 'p95', 'ms', 0), tk('P99', 'p99', 'ms', 0), tk('Avg response', 'avgRt', 'ms', 0), tk('Throughput', 'tps', 'TPS', 1), tk('Error rate', 'errorPct', '%', 2), tk('SLA compliance', 'slaPassPct', '%', 1), tk('Score', 'score', '/100', 0),
  ] satisfies Kpi[], note: 'Deltas compare the latest run with the first run in the period; status reflects the detected trend direction.' });

  sections.push(chapter('ch-charts', 'KPI trends', 'One point per completed run, in execution order.'));
  if (pts.length > 1) {
    const line = (k: TrendMetric, d: number) => pts.map((p) => [t(p), r2(p.metrics[k], d)] as [number, number | null]);
    sections.push(chart('chart-rt', 'Response time', { type: 'line', unit: 'ms', yLabel: 'Response time (ms)', xType: 'time', series: [{ name: 'P99', data: line('p99', 0), style: 'dashed' }, { name: 'P95', data: line('p95', 0) }, { name: 'Average', data: line('avgRt', 0), style: 'dotted' }] }, approx ? 'Some runs report approximate percentiles (≈).' : undefined));
    sections.push(chart('chart-tps', 'Throughput', { type: 'line', unit: 'TPS', yLabel: 'TPS', xType: 'time', series: [{ name: 'Average TPS', data: line('tps', 1) }] }));
    sections.push(chart('chart-err', 'Error rate', { type: 'line', unit: '%', yLabel: 'Errors (%)', xType: 'time', series: [{ name: 'Error rate', data: line('errorPct', 2) }] }));
    if (pts.some((p) => p.metrics.slaPassPct != null)) sections.push(chart('chart-sla', 'SLA compliance', { type: 'line', unit: '%', yLabel: 'Compliance (%)', xType: 'time', series: [{ name: 'SLA compliance', data: line('slaPassPct', 1) }] }));
    if (pts.some((p) => p.metrics.score != null)) sections.push(chart('chart-score', 'Performance score', { type: 'line', unit: 'pts', yLabel: 'Score', xType: 'time', series: [{ name: 'Score', data: line('score', 0) }] }));
    if (pts.some((p) => p.metrics.cpuAvg != null)) sections.push(chart('chart-cpu', 'Average CPU (application servers)', { type: 'line', unit: '%', yLabel: 'CPU (%)', xType: 'time', series: [{ name: 'CPU avg', data: line('cpuAvg', 1) }] }));
  } else sections.push({ id: 'no-trend', title: 'Trend charts', kind: 'text', data: 'At least two completed runs are needed to draw trends.' });
  sections.push(table('signals', 'Trend signals', [col('metric', 'Metric'), col('direction', 'Direction', 'status'), col('change', 'Change'), col('slope', 'Slope / run', 'num'), col('r2', 'R²', 'num'), col('consecutive', 'Consecutive worse', 'int'), col('severity', 'Severity', 'status')],
    sig.map((d) => ({ metric: TREND_METRICS[d.metric as TrendMetric]?.label ?? d.metric, direction: d.direction === 'DEGRADING' ? 'WORSE' : d.direction === 'IMPROVING' ? 'BETTER' : 'STABLE', change: trendChange(d.metric as TrendMetric, pts), slope: r2(d.slopePerStep, 3), r2: r2(d.r2, 2), consecutive: d.consecutiveWorse, severity: d.direction === 'DEGRADING' ? d.severity : null })),
    sig.length ? 'Direction uses an OLS slope over the run index (R² ≥ 0.5 and a significant total change) or ≥ 3 consecutive worsening runs.' : 'At least three runs are needed to classify trends.'));

  sections.push(chapter('ch-runs', 'Runs & transactions', 'Every run in the period and how its transactions evolved.'));
  sections.push(table('runs', 'Runs', [col('runKey', 'Run ID', 'mono'), col('started', 'Started', 'date'), col('build', 'Build'), col('users', 'VUs', 'int'), col('result', 'Result', 'status'), col('p95', 'P95', 'int', 'ms', approx), col('dp95', 'Δ P95', 'delta', '%'), col('p99', 'P99', 'int', 'ms', approx), col('avg', 'Avg', 'int', 'ms'), col('tps', 'TPS', 'num1'), col('err', 'Err', 'pct', '%'), col('sla', 'SLA', 'pct', '%'), col('score', 'Score', 'int')],
    [...pts].reverse().map((p, i, arr) => { const prev = arr[i + 1]; const x = ex.get(p.runId); return { runKey: p.runKey, started: p.startedAt, build: p.buildNumber ?? '—', users: n(x?.users_peak) ?? n(x?.virtual_users), result: x?.result ?? null, p95: r2(p.metrics.p95, 0), dp95: prev ? r2(delta(p.metrics.p95, prev.metrics.p95), 1) : null, p99: r2(p.metrics.p99, 0), avg: r2(p.metrics.avgRt, 0), tps: r2(p.metrics.tps, 1), err: r2(p.metrics.errorPct), sla: r2(p.metrics.slaPassPct, 1), score: r2(p.metrics.score, 0) }; }),
    'Latest first. Δ P95 is the change versus the previous run.'));
  const lastIds = ids.slice(-10);
  if (lastIds.length > 1) {
    const tx = await query(`SELECT DISTINCT ON (t.run_id, t.name) t.run_id, t.name, t.p95, t.samples, t.error_pct FROM transactions t WHERE t.run_id = ANY($1::uuid[])
                            ORDER BY t.run_id, t.name, CASE t.source WHEN 'live' THEN 0 WHEN 'jtl' THEN 1 WHEN 'import' THEN 2 ELSE 3 END`, [lastIds]);
    const byName = new Map<string, Map<string, any>>();
    for (const x of tx) { const m = byName.get(x.name) ?? new Map(); m.set(x.run_id, x); byName.set(x.name, m); }
    const lastId = lastIds[lastIds.length - 1];
    const rows = [...byName.entries()].map(([name, m]) => {
      const seq = lastIds.map((id) => r2(m.get(id)?.p95, 0));
      const vals = seq.filter((v): v is number => v != null);
      const firstV = vals[0] ?? null, lastV = m.get(lastId) ? r2(m.get(lastId).p95, 0) : null;
      return { name, samples: n(m.get(lastId)?.samples), first: firstV, latest: lastV, change: r2(delta(lastV, firstV), 1), min: vals.length ? Math.min(...vals) : null, max: vals.length ? Math.max(...vals) : null, err: r2(m.get(lastId)?.error_pct), trend: seq };
    }).filter((x) => x.latest != null).sort((a, b) => (b.samples ?? 0) - (a.samples ?? 0)).slice(0, 25);
    sections.push(table('txn-trends', `Transaction P95 across the last ${lastIds.length} runs`, [col('name', 'Transaction'), col('samples', 'Samples (latest)', 'int'), col('first', 'First P95', 'int', 'ms', approx), col('latest', 'Latest P95', 'int', 'ms', approx), col('change', 'Change', 'delta', '%'), col('min', 'Min', 'int', 'ms'), col('max', 'Max', 'int', 'ms'), col('err', 'Err (latest)', 'pct', '%'), col('trend', 'P95 trend', 'spark')], rows,
      'Top 25 transactions by latest volume. The spark line shows P95 per run, oldest to newest.'));
  }
  sections.push(table('regressions', 'Regressions recorded in the period', [col('runKey', 'Run', 'mono'), col('severity', 'Severity', 'status'), col('scope', 'Scope'), col('metric', 'Metric'), col('previous', 'Baseline', 'num'), col('current', 'Current', 'num'), col('change', 'Change', 'delta', '%')],
    regs.map((g) => ({ runKey: g.run_key, severity: g.severity, scope: g.transaction ?? g.scope, metric: metricName(g.metric), previous: r2(g.previous_value), current: r2(g.current_value), change: r2(g.change_pct, 1) })), regs.length ? undefined : 'No regressions recorded.'));

  let capacity: Awaited<ReturnType<typeof capacityModel>> | null = null;
  try { capacity = await capacityModel({ orgId: opts.orgId, projectId: opts.projectId, testId: opts.testId, environmentId: opts.environmentId }); } catch { capacity = null; }
  if (capacity) {
    sections.push(chapter('ch-capacity', 'Capacity estimate', 'Latency-versus-load model fitted across the completed runs of this test. Every figure here is an estimate.'));
    sections.push(kv('capacity', 'Model', [['Latency model', capacity.model.description], ['Estimated saturation', capacity.estimatedSaturationTps != null ? `≈ ${fmtNum(capacity.estimatedSaturationTps, 1)} TPS` : 'Not enough data'], ['Latest throughput', `${fmtNum(last?.metrics.tps, 1)} TPS`],
      ['Estimated headroom', capacity.estimatedSaturationTps != null && last?.metrics.tps != null ? `≈ ${fmtNum(((capacity.estimatedSaturationTps - last.metrics.tps) / capacity.estimatedSaturationTps) * 100, 0)}%` : 'n/a'], ['Runs used', capacity.observations.length], ['P95 SLA', capacity.slaP95 != null ? `${fmtNum(capacity.slaP95, 0)} ms` : '—']], capacity.notes.join(' ')));
  }
  sections.push(chapter('ch-appendix', 'Appendix', 'Glossary, methodology and report metadata.'));
  sections.push(kv('glossary', 'Glossary of metrics', GLOSSARY));
  sections.push({ id: 'methodology', title: 'Methodology', kind: 'list', data: [...methodology(approx ? 'interval_weighted_approx' : null).slice(0, 3), 'Each trend point is one completed run of the test (primary data source of that run). Trend direction uses an OLS slope over the run index plus the number of consecutive worsening runs; relative metrics need ≥5% total change, absolute metrics (error %, SLA %, CPU, score) a fixed number of points.'] });
  sections.push(kv('metadata', 'Report metadata', [['Report type', 'Trend'], ['Report version', `v${version}`], ['Generated', new Date().toISOString()], ['Project', names.project ?? '—'], ['Test', names.test ?? '—'], ['Environment filter', names.environment ?? 'All environments'], ['Period', periodText(opts.from, opts.to)]]));

  const status = !pts.length ? 'INCONCLUSIVE' : degr.some((d) => d.severity === 'CRITICAL') ? 'FAIL' : degr.length ? 'PASS_WITH_WARNINGS' : pts.length >= 3 ? 'PASS' : 'INCONCLUSIVE';
  return {
    title, type: 'TREND', generatedAt: new Date().toISOString(), version, audience: 'ENGINEERING', schema: 2, confidentiality: CONFIDENTIALITY,
    subject: { projectName: names.project, testName: names.test, environment: names.environment, from: opts.from.toISOString(), to: opts.to.toISOString() },
    result: { status, score: r2(last?.metrics.score, 0), breakdown: Object.fromEntries((['p95', 'tps', 'errorPct', 'slaPassPct'] as TrendMetric[]).map((k) => { const d = sig.find((x) => x.metric === k); return [TREND_METRICS[k].label.replace(' (TPS)', ''), !d ? 'N/A' : d.direction === 'DEGRADING' ? (d.severity === 'CRITICAL' ? 'FAIL' : 'WARNING') : 'PASS']; })) },
    cover: { label: 'Trend report', facts: [['Test', names.test ?? '—'], ['Project', names.project ?? '—'], ['Environment', names.environment ?? 'All'], ['Period', periodText(opts.from, opts.to)], ['Runs', String(pts.length)], ['Latest run', last?.runKey ?? '—']] },
    sections,
  };
}

/* ------------------------------------------------------------------ formatting (shared with renderers) */

export function fmtNum(v: number | null | undefined, d = 2) { return v == null || !Number.isFinite(v) ? 'n/a' : v.toLocaleString('en-US', { maximumFractionDigits: d, minimumFractionDigits: 0 }); }
export function fmtSigned(v: number | null | undefined, d = 1) { return v == null || !Number.isFinite(v) ? 'n/a' : `${v > 0 ? '+' : v < 0 ? '−' : ''}${fmtNum(Math.abs(v), d)}`; }
export function fmtInt(v: number | null | undefined) { return fmtNum(v, 0); }
export function fmtMs(v: number | null | undefined) { return v == null || !Number.isFinite(v) ? 'n/a' : v >= 1000 ? `${fmtNum(v / 1000, 2)} s` : `${fmtNum(v, 0)} ms`; }
export function fmtDur(sec: number | null | undefined) {
  if (sec == null || !Number.isFinite(sec)) return 'n/a';
  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = Math.round(sec % 60);
  return h ? `${h}h ${m}m` : m ? `${m}m ${s}s` : `${s}s`;
}
export { sevRank };
